/** All translations for zizhitongjian ch.011 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起屠維大淵獻，盡重光赤奮若，凡三年。", literal: "From Tuwu Dayuanxian through Chongguang Chifenruo; three years in all.", idiomatic: "From Tuwu Dayuanxian through Chongguang Chifenruo—three years in all." },
  { zh: "1冬，十月，漢王追項羽至固陵，與齊王信、魏相國越期會擊楚；", literal: "1. In winter, the tenth month, the king of Han pursued Xiang Yu to Guling and arranged with the king of Qi Xin and the chancellor of Wei Yue a rendezvous to strike Chu;", idiomatic: "1. In the tenth month of winter the king of Han pursued Xiang Yu to Guling and arranged with King Xin of Qi and Chancellor Yue of Wei a joint strike against Chu;" },
  { zh: "信、越不至，楚擊漢軍，大破之。", literal: "Xin and Yue did not come; Chu struck the Han army and routed it utterly.", idiomatic: "Xin and Yue never came. Chu struck the Han army and broke it utterly." },
  { zh: "漢王復堅壁自守，謂張良曰：「諸侯不從，奈何？", literal: "The king of Han again held fast behind walls and kept to himself, saying to Zhang Liang: \"The feudal lords do not follow—what is to be done?", idiomatic: "The king of Han again held his walls and kept to camp. He said to Zhang Liang: \"The lords will not follow—what now?\"" },
  { zh: "」對曰：「楚兵且破，二人未有分地，其不至固宜。", literal: "\" He replied: \"Chu's troops are near breaking; the two have no allotted lands yet—for them not to come is surely fitting.", idiomatic: "\" He replied: \"Chu's army is near breaking, yet those two have no fiefs allotted them—for them not to come is only natural." },
  { zh: "君王能與共天下，可立致也。", literal: "If your majesty can share all under Heaven with them, they may be brought at once.", idiomatic: "Share the realm with them, and they will come at once." },
  { zh: "齊王信之立，非君王意，信亦不自堅；", literal: "The king of Qi Xin's elevation was not your majesty's intent, and Xin himself is not firmly secure;", idiomatic: "King Xin of Qi was not raised by your will, and Xin himself stands on uncertain ground;" },
  { zh: "彭越本定梁地，始，君王以魏豹故拜越為相國，今豹死，越亦望王，而君王不早定。", literal: "Peng Yue had originally pacified Liang. At first your majesty made Yue chancellor because of Wei Bao; now Bao is dead, and Yue also looks to your majesty for kingship—yet your majesty has not fixed this early.", idiomatic: "Peng Yue pacified Liang in the first place. You made him chancellor on Wei Bao's account; Bao is dead now, and Yue too looks to you for a kingdom—yet you have not settled it early." },
  { zh: "今能取睢陽以北至穀城皆以王彭越，從陳以東傅海與齊王信。", literal: "If you can now make Peng Yue king over all from north of Suiyang to Gucheng, and give the king of Qi Xin all east from Chen to the sea—", idiomatic: "Make Peng Yue king of all from north of Suiyang to Gucheng, and give King Xin of Qi everything east from Chen to the sea." },
  { zh: "信家在楚，其意欲復得故邑。", literal: "Xin's family is in Chu; his heart wishes to recover his old fief.", idiomatic: "Xin's kin are in Chu; his heart is set on recovering his old lands." },
  { zh: "能出捐此地以許兩人，使各自為戰，則楚易破也。", literal: "If you can release and pledge these lands to the two, and let each fight on his own account, then Chu will be easy to break.", idiomatic: "Pledge these lands to both and let each fight on his own account, and Chu will be easy to break.\"" },
  { zh: "」漢王從之。", literal: "\" The king of Han followed this counsel.", idiomatic: "\" The king of Han took his advice." },
  { zh: "於是韓信、彭越皆引兵來。", literal: "Thereupon Han Xin and Peng Yue both led their troops to come.", idiomatic: "Then Han Xin and Peng Yue both brought their armies." },
  { zh: "十一月，劉賈南渡淮，圍壽春，遣人誘楚大司馬周殷。", literal: "In the eleventh month Liu Jia crossed the Huai southward, besieged Shouchun, and sent men to entice Chu Grand Marshal Zhou Yin.", idiomatic: "In the eleventh month Liu Jia crossed the Huai south, besieged Shouchun, and sent men to win over Chu's Grand Marshal Zhou Yin." },
  { zh: "殷畔楚，以舒屠六，舉九江兵迎黥布，並行屠城父，隨劉賈皆會。", literal: "Yin turned from Chu, took Shu to sack Liu, raised the troops of Jiujiang to welcome Qing Bu, marched together sacking Chengf, and all joined Liu Jia.", idiomatic: "Yin turned against Chu, took Shu and sacked Liu, raised the armies of Jiujiang to welcome Qing Bu, marched together sacking Chengf, and all joined Liu Jia." },
  { zh: "十二月，項王至垓下，兵少，食盡，與漢戰不勝，入壁；", literal: "In the twelfth month the king of Xiang reached Gaixia; his troops were few, provisions exhausted; he fought Han and could not win, and entered his camp;", idiomatic: "In the twelfth month the Overlord of Xiang reached Gaixia. His troops were few, his grain gone; he fought Han and could not win, and withdrew into camp;" },
  { zh: "漢軍及諸侯兵圍之數重。", literal: "Han troops and the feudal lords' armies surrounded him in many rings.", idiomatic: "Han troops and the allied armies ringed him round and round." },
  { zh: "項王夜聞漢軍四面皆楚歌，乃大驚曰：「漢皆已得楚乎？", literal: "By night the king of Xiang heard that on all four sides of the Han army there were Chu songs; he was greatly alarmed and said: \"Has Han already taken Chu?", idiomatic: "By night the Overlord heard Chu songs on every side of the Han camp. He started in alarm: \"Has Han taken all of Chu?" },
  { zh: "是何楚人之多也？", literal: "How is it that there are so many men of Chu?", idiomatic: "How can there be so many men of Chu?\"" },
  { zh: "」則夜起，飲帳中，悲歌慷慨，泣數行下；", literal: "\" He then rose in the night, drank in his tent, sang a song bold with sorrow, and tears ran down in several streams;", idiomatic: "\" He rose in the night, drank in his tent, and sang—a song fierce with sorrow—while tears streamed down his face;" },
  { zh: "左右皆泣，莫能仰視。", literal: "Those about him all wept; none could lift their faces to look up.", idiomatic: "Those about him wept; none could raise his eyes to look." },
  { zh: "於是項王乘其駿馬名騅，麾下壯士騎從者八百餘人，直夜，潰圍南出馳走。", literal: "Thereupon the king of Xiang mounted his swift steed named Zhui; more than eight hundred picked horsemen among his command rode after him; at midnight he burst the encirclement and fled south at a gallop.", idiomatic: "Then the Overlord mounted his swift steed Zhui, with more than eight hundred picked riders at his command. At midnight he broke the encirclement and fled south at a gallop." },
  { zh: "平明，漢軍乃覺之，令騎將灌嬰以五千騎追之。", literal: "At dawn the Han army only then noticed; they ordered the cavalry general Guan Ying with five thousand horsemen to pursue him.", idiomatic: "At dawn the Han army only then took notice and sent the cavalry general Guan Ying with five thousand riders in pursuit." },
  { zh: "項王渡淮，騎能屬者才百餘人。", literal: "The king of Xiang crossed the Huai; horsemen who could still follow numbered scarcely a hundred and more.", idiomatic: "The Overlord crossed the Huai; scarcely a hundred riders could still keep with him." },
  { zh: "至陰陵，迷失道，問一田父，田父紿曰「左」。", literal: "Reaching Yingling he lost the road and asked a farmer; the farmer deceived him, saying \"Left.\"", idiomatic: "At Yingling he lost the road and asked a farmer, who lied and said, \"Go left.\"" },
  { zh: "左，乃陷大澤中，以故漢追及之。", literal: "Left—and he sank into a great marsh; for this reason Han caught up with him.", idiomatic: "He went left and sank into a great marsh—and so Han caught up." },
  { zh: "項王乃復引兵而東，至東城，乃有二十八騎。", literal: "The king of Xiang then again led troops eastward; reaching Dongcheng he had only twenty-eight horsemen.", idiomatic: "The Overlord turned east again. At Dongcheng he had only twenty-eight riders left." },
  { zh: "漢騎追者數千人，項王自度不得脫，謂其騎曰：「吾起兵至今，八歲矣；", literal: "Han horsemen pursuing numbered several thousands. The king of Xiang judged for himself that he could not escape, and said to his riders: \"From the day I raised arms until now, eight years have passed;", idiomatic: "Thousands of Han riders pressed behind him. The Overlord knew he could not escape and said to his men: \"From the day I raised arms, eight years have passed;" },
  { zh: "身七十餘戰，未嘗敗北，遂霸有天下。", literal: "I myself have fought more than seventy battles and never once been defeated northward; thus I came to hegemony and possession of all under Heaven.", idiomatic: "I have fought more than seventy battles and never once been turned back—until I held the realm." },
  { zh: "然今卒困於此，此天之亡我，非戰之罪也。", literal: "Yet now I am suddenly trapped here—this is Heaven destroying me, not the crime of battle.", idiomatic: "Yet now I am trapped here. Heaven is destroying me—not the fault of war." },
  { zh: "今日固決死，願為諸君快戰，必潰圍，斬將，刈旗，三勝之，令諸君知天亡我，非戰之罪也。", literal: "Today I am firmly resolved to die; I wish to fight a swift battle for you gentlemen—I shall surely break the encirclement, behead generals, and cut down banners, win three victories, and let you gentlemen know that Heaven is destroying me, not the crime of battle.", idiomatic: "Today I am resolved to die. I will fight one swift battle for you—I shall break the ring, behead their generals, cut down their banners, win three victories, and show you that Heaven is destroying me, not the fault of war.\"" },
  { zh: "」乃分其騎以為四隊，四鄉。", literal: "\" He then divided his horsemen into four companies facing the four directions.", idiomatic: "\" He divided his riders into four companies facing the four directions." },
  { zh: "漢軍圍之數重。", literal: "The Han army surrounded them in many rings.", idiomatic: "The Han army ringed them round and round." },
  { zh: "項王謂其騎曰：「吾為公取彼一將。", literal: "The king of Xiang said to his riders: \"I will take that one general for you gentlemen.", idiomatic: "The Overlord said to his riders: \"I will take that general for you.\"" },
  { zh: "」令四面騎馳下，期山東為三處。", literal: "\" He ordered the horsemen on all sides to gallop down and meet east of the mountain in three places.", idiomatic: "\" He ordered his riders on every side to charge down and rally east of the hill in three groups." },
  { zh: "於是項王大呼馳下，漢軍皆披靡，遂斬漢一將。", literal: "Thereupon the king of Xiang shouted and galloped down; the Han army all scattered before him, and he beheaded one Han general.", idiomatic: "The Overlord shouted and charged down. The Han ranks scattered before him, and he cut down one Han general." },
  { zh: "是時，郎中騎楊喜追項王，項王瞋目而叱之，喜人馬俱驚，辟易數里。", literal: "At that time the attendant-rider Yang Xi pursued the king of Xiang; the king glared and shouted at him; Xi's man and horse were both alarmed and gave way for several li.", idiomatic: "Then attendant-rider Yang Xi gave chase. The Overlord glared and roared at him; Xi's horse and rider both recoiled and fell back several li." },
  { zh: "項王與其騎會為三處，漢軍不知項王所在，乃分軍為三，復圍之。", literal: "The king of Xiang and his riders met in three places; the Han army did not know where the king of Xiang was and divided the army in three to surround them again.", idiomatic: "The Overlord and his riders rallied in three groups. Not knowing where he was, the Han army split in three and surrounded them again." },
  { zh: "項王乃馳，復斬漢一都尉，殺數十百人。", literal: "The king of Xiang then galloped, again beheaded one Han commandant, and killed several tens to hundreds of men.", idiomatic: "The Overlord charged again, cut down one Han commandant, and killed scores of men." },
  { zh: "復聚其騎，亡其兩騎耳。", literal: "He gathered his riders again—only two horsemen lost.", idiomatic: "He gathered his riders again—only two were lost." },
  { zh: "乃謂其騎曰：「何如？", literal: "He then said to his riders: \"How was that?", idiomatic: "He said to his riders: \"How was that?\"" },
  { zh: "」騎皆伏曰：「如大王言！", literal: "\" The riders all bowed low and said: \"As the great king said!", idiomatic: "\" The riders all bowed low. \"As my lord said!\"" },
  { zh: "於是項王欲東渡烏江，烏江亭長艤船待，謂項王曰：「江東雖小，地方千里，眾數十萬人，亦足王也。", literal: "Thereupon the king of Xiang wished to cross the Wu River eastward; the Wu River station-chief moored his boat and waited, saying to the king of Xiang: \"Though Jiangdong is small, its territory is a thousand li, its masses number several hundred thousand—enough to be king still.", idiomatic: "Then the Overlord meant to cross the Wu River east. The river station-chief moored his boat and waited. He said: \"Jiangdong is small, but a thousand li across and hundreds of thousands strong—enough to make you king still." },
  { zh: "願大王急渡！", literal: "I beg the great king to cross in haste!", idiomatic: "Cross now, my lord—at once!\"" },
  { zh: "今獨臣有船，漢軍至，無以渡。", literal: "Now only your servant has a boat; when the Han army arrives there will be no means to cross.", idiomatic: "I alone have a boat. When the Han army comes, there will be no crossing." },
  { zh: "」項王笑曰：「天之亡我，我何渡為！", literal: "\" The king of Xiang laughed and said: \"Heaven is destroying me—why should I cross!", idiomatic: "\" The Overlord laughed. \"Heaven is destroying me—why should I cross?" },
  { zh: "且籍與江東子弟八千人渡江而西，今無一人還；", literal: "Moreover, Ji with eight thousand youths of Jiangdong crossed the river westward, and today not one returns;", idiomatic: "Ji led eight thousand youths of Jiangdong west across the river, and not one returns;" },
  { zh: "縱江東父兄憐而王我，我何面目見之！", literal: "even if the fathers and elders of Jiangdong pitied me and made me king, with what face could I meet them!", idiomatic: "even if the fathers and elders of Jiangdong pitied me and made me king—what face have I to meet them!" },
  { zh: "縱彼不言，籍獨不愧於心乎！", literal: "Even if they said nothing, would Ji alone not be ashamed in his heart!", idiomatic: "Even if they said nothing—would Ji not be ashamed in his own heart!\"" },
  { zh: "」乃以所乘騅馬賜亭長，令騎皆下馬步行，持短兵接戰。", literal: "\" He then gave the steed Zhui he rode to the station-chief, ordered all riders to dismount and go on foot, took short weapons and joined battle.", idiomatic: "\" He gave his steed Zhui to the station-chief, ordered every rider to dismount and fight on foot with short weapons." },
  { zh: "獨籍所殺漢軍數百人，身亦被十餘創。", literal: "Ji alone killed several hundreds of Han soldiers, and his body also received more than ten wounds.", idiomatic: "Ji alone killed hundreds of Han soldiers and took more than ten wounds." },
  { zh: "顧見漢騎司馬呂馬童，曰：「若非吾故人乎？", literal: "Looking back he saw Han cavalry marshal Lü Matong and said: \"Are you not an old acquaintance of mine?", idiomatic: "He glanced back and saw Han cavalry marshal Lü Matong. \"Are you not an old friend of mine?\"" },
  { zh: "」馬童面之，指示中郎騎王翳曰：「此項王也！", literal: "\" Matong turned his face toward him and pointed him out to attendant-cavalry Wang Yi, saying: \"This is the king of Xiang!", idiomatic: "\" Matong turned toward him and pointed him out to attendant-cavalry Wang Yi: \"This is the Overlord of Xiang!\"" },
  { zh: "」項王乃曰：「吾聞漢購我頭千金，邑萬戶，吾為若德。", literal: "\" The king of Xiang then said: \"I have heard Han offers a thousand gold for my head and a fief of ten thousand households—I will do you this kindness.", idiomatic: "\" The Overlord said: \"I hear Han offers a thousand in gold for my head and a fief of ten thousand households. I do you this kindness.\"" },
  { zh: "」乃刎而死。", literal: "\" He then cut his throat and died.", idiomatic: "\" He cut his throat and died." },
  { zh: "王翳取其頭，餘騎相蹂踐爭項王，相殺者數十人。", literal: "Wang Yi took his head; the remaining riders trampled and fought over the king of Xiang, and several tens killed one another.", idiomatic: "Wang Yi took his head. The other riders trampled one another fighting over the body, and dozens killed one another in the scramble." },
  { zh: "最其後，楊喜、呂馬童及郎中呂勝、楊武各得其一體；", literal: "In the end Yang Xi, Lü Matong, and attendants Lü Sheng and Yang Wu each obtained one part of the body;", idiomatic: "In the end Yang Xi, Lü Matong, and attendants Lü Sheng and Yang Wu each seized a piece of the body;" },
  { zh: "五人共會其體，皆是，故分其戶，封五人皆為列侯。", literal: "the five joined their parts together—it was all him—so they divided his household and enfeoffed all five as marquises.", idiomatic: "the five fitted the pieces together—it was all him—so they divided his reward and enfeoffed all five as marquises." },
  { zh: "楚地悉定，獨魯不下；", literal: "Chu's lands were all settled; only Lu would not submit;", idiomatic: "All Chu was pacified; only Lu held out;" },
  { zh: "漢王引天下兵欲屠之。", literal: "the king of Han led the armies of all under Heaven intending to slaughter it.", idiomatic: "and the king of Han led the armies of the realm intending to slaughter it." },
  { zh: "至其城下，猶聞弦誦之聲，為其守禮義之國，為主死節，乃持項王頭以示魯父兄，魯乃降。", literal: "Reaching beneath its walls he still heard the sounds of strings and recitation; because it was a state that kept ritual and righteousness and died in integrity for its lord, he took the head of the king of Xiang to show the fathers and elders of Lu, and Lu then submitted.", idiomatic: "Beneath its walls he still heard the sound of strings and recitation. Because Lu was a state of ritual and righteousness that died for its lord, he showed the Overlord's head to Lu's elders—and Lu submitted." },
  { zh: "漢王以魯公禮葬項王於穀城，親為發哀，哭之而去。", literal: "The king of Han buried the king of Xiang at Gucheng with the rites due a lord of Lu, personally set the mourning in motion, wept for him and departed.", idiomatic: "The king of Han buried the Overlord at Gucheng with the rites due a lord of Lu, personally led the mourning, wept, and departed." },
  { zh: "諸項氏枝屬皆不誅。", literal: "All branches and kin of the Xiang clan were not executed.", idiomatic: "No branch of the Xiang clan was put to death." },
  { zh: "封項伯等四人皆為列侯，賜姓劉氏；", literal: "He enfeoffed Xiang Bo and four others all as marquises and granted them the surname Liu;", idiomatic: "He enfeoffed Xiang Bo and four others as marquises and granted them the surname Liu;" },
  { zh: "諸民略在楚者皆歸之。", literal: "all commoners who had been seized in Chu were returned home.", idiomatic: "and every commoner seized in Chu was sent home." },
  { zh: "::太史公曰：羽起隴晦之中，三年，遂將五諸侯滅秦，分裂天下而封王侯，政由羽出；", literal: ":: The Grand Scribe observes: Yu rose from among fields and marshes; in three years he led the five feudal lords to destroy Qin, divided all under Heaven and enfeoffed kings and marquises, and government issued from Yu;", idiomatic: ":: The Grand Scribe writes: Yu rose from the fields and marshes; in three years he led the five lords to destroy Qin, divided the realm and enfeoffed kings and marquises, and government flowed from his hand;" },
  { zh: "位雖不終，近古以來未嘗有也！", literal: "though his position did not reach its end, since near antiquity there has never been such a case!", idiomatic: "his throne did not last—but since near antiquity there had never been his like!" },
  { zh: "及羽背關懷楚，放逐義帝而自立；", literal: "When Yu turned his back on the passes and yearned for Chu, banished the Righteous Emperor and set himself up—", idiomatic: "When Yu turned his back on the passes for love of Chu, banished the Righteous Emperor, and set himself up—" },
  { zh: "怨王侯叛己，難矣！", literal: "to resent kings and marquises who turned from him—then it was hard!", idiomatic: "to resent every lord who turned from him—then the end was already written." },
  { zh: "自矜功伐，奮其私智而不師古，謂霸王之業，欲以力征經營天下。", literal: "Proud of his merit, vaunting his victories, he exerted his private wits and would not take antiquity as teacher; he deemed the hegemon-king's enterprise and wished to manage all under Heaven by force of arms alone.", idiomatic: "Proud of his victories, trusting his own wit and scorning the ancients, he thought the hegemon's work could be done by force alone." },
  { zh: "五年，卒亡其國，身死東城，尚不覺寤而不自責，乃引「天亡我，非用兵之罪也，」豈不謬哉！", literal: "In five years he at last lost his state; his person died at Dongcheng, yet he still did not wake and would not blame himself, but quoted \"Heaven is destroying me—it is not the crime of using troops\"—is this not absurd!", idiomatic: "Five years later he lost his kingdom and died at Dongcheng—yet he never woke, never blamed himself, but quoted, \"Heaven is destroying me; it is not the fault of war.\" Can anything be more absurd?" },
  { zh: "::揚子《法言》：或問：「楚敗垓下，方死，曰『天也！", literal: ":: Yang Xiong's Fa Yan: Someone asked: \"Chu was defeated at Gaixia; facing death he said 'It is Heaven!", idiomatic: ":: Yang Xiong's Fa Yan: Someone asked: \"Chu was broken at Gaixia. Facing death Xiang Yu said, 'It is Heaven!'" },
  { zh: "』諒乎？", literal: "' Is this to be believed?", idiomatic: "' Is that to be believed?\"" },
  { zh: "」曰：「漢屈群策，群策屈群力；", literal: "\" He said: \"Han bent the many stratagems, and the many stratagems bent the many strengths;", idiomatic: "\" He answered: \"Han bent every stratagem to its will, and every stratagem bent every strength;" },
  { zh: "楚敦群策而自屈其力。", literal: "Chu heaped up the many stratagems yet bent its own strength.", idiomatic: "Chu hoarded stratagems yet bent its own strength." },
  { zh: "屈人者克，自屈者負。", literal: "One who bends others conquers; one who bends himself is defeated.", idiomatic: "He who bends others conquers; he who bends himself is defeated." },
  { zh: "天曷故焉！", literal: "What has Heaven to do with it!", idiomatic: "What has Heaven to do with it?\"" },
  { zh: "2漢王還，至定陶，馳入齊王信壁，奪其軍。", literal: "2. The king of Han returned, reached Dingtao, galloped into the king of Qi Xin's camp, and seized his army.", idiomatic: "2. The king of Han returned to Dingtao, galloped into King Xin of Qi's camp, and seized his army." },
  { zh: "3臨江王共尉不降，遣盧綰、劉賈擊虜之。", literal: "3. The king of Linjiang Gong Wei did not submit; he sent Lu Wan and Liu Jia to strike and capture him.", idiomatic: "3. King Gong Wei of Linjiang would not submit. He sent Lu Wan and Liu Jia to strike and capture him." },
  { zh: "4春，正月，更立齊王信為楚王，王淮北，都下邳。", literal: "4. In spring, the first month, he changed and established the king of Qi Xin as king of Chu, enfeoffing him over Huaibei with capital at Xiapi.", idiomatic: "4. In spring, the first month, he made King Xin of Qi king of Chu over Huaibei, with his capital at Xiapi." },
  { zh: "封魏相國建城侯彭越為梁王，王魏故地，都定陶。", literal: "He enfeoffed the chancellor of Wei, Marquis of Jiancheng Peng Yue, as king of Liang, king over Wei's former lands with capital at Dingtao.", idiomatic: "He made Chancellor Peng Yue of Wei, Marquis of Jiancheng, king of Liang over Wei's former lands, with his capital at Dingtao." },
  { zh: "5令曰：「兵不得休八年，萬民與苦甚。", literal: "5. An order stated: \"Arms have not rested for eight years; the myriad people suffer greatly with them.", idiomatic: "5. An edict ran: \"Arms have not rested for eight years, and the people have suffered greatly." },
  { zh: "今天下事畢，其赦天下殊死以下。", literal: "Now that affairs under Heaven are concluded, let there be amnesty in all under Heaven for offenses below capital crime.", idiomatic: "Now that the realm is settled, let there be amnesty throughout the land for all crimes short of death.\"" },
  { zh: "6諸侯王皆上疏請尊漢王為皇帝。", literal: "6. The kings among the feudal lords all submitted memorials asking that the king of Han be honored as emperor.", idiomatic: "6. The feudal kings all submitted memorials asking that the king of Han be honored as emperor." },
  { zh: "二月甲午，王即皇帝位於汜水之陽。", literal: "On jiawu of the second month the king ascended the emperor's throne south of the Si River.", idiomatic: "On jiawu of the second month the king took the throne as emperor south of the Si River." },
  { zh: "更王后曰皇后，太子曰皇太子；", literal: "He changed the queen-consort's title to empress and the heir's to crown prince;", idiomatic: "He renamed the queen-consort empress and the heir crown prince;" },
  { zh: "追尊先媼曰昭靈夫人。", literal: "and posthumously honored his late mother as Lady Zhaoling.", idiomatic: "and posthumously honored his late mother as Lady Zhaoling." },
  { zh: "詔曰：「故衡山王吳芮，從百粵之兵，佐諸侯，誅暴秦，有大功；", literal: "An edict stated: \"The former king of Hengshan Wu Rui, with the armies of the Hundred Yue, aided the feudal lords, punished violent Qin, and had great merit;", idiomatic: "An edict stated: \"The former king of Hengshan, Wu Rui, led the armies of the Hundred Yue to aid the lords in punishing tyrannical Qin and won great merit;" },
  { zh: "諸侯立以為王，項羽侵奪之地，謂之番君。", literal: "the feudal lords set him up as king; the lands Xiang Yu seized and stole away—they called him Lord Fan.", idiomatic: "the lords made him king, but Xiang Yu seized his lands and called him Lord Fan." },
  { zh: "其以芮為長沙王。", literal: "Let Rui be made king of Changsha.", idiomatic: "Let Rui be king of Changsha.\"" },
  { zh: "」又曰：「故粵王無諸，世奉粵祀；", literal: "\" It also stated: \"The former king of Yue Wu Zhu, generation after generation offering Yue sacrifices;", idiomatic: "\" It also stated: \"The former king of Yue, Wu Zhu, offered Yue sacrifices generation after generation;" },
  { zh: "秦侵奪其地，使其社稷不得血食。", literal: "Qin invaded and seized his lands so that his altars and grain could not receive blood-offerings.", idiomatic: "yet Qin seized his lands so that his altars could receive no offerings." },
  { zh: "諸侯伐秦，無諸身率閩中兵以佐滅秦，項羽廢而弗立。", literal: "When the feudal lords attacked Qin, Wu Zhu personally led the troops of Minzhong to aid in destroying Qin; Xiang Yu deposed him and would not establish him.", idiomatic: "When the lords attacked Qin, Wu Zhu personally led the armies of Minzhong to help destroy Qin, but Xiang Yu deposed him and would not restore him." },
  { zh: "今以為閩粵王，王閩中地。", literal: "Now let him be made king of Minyue, king over the lands of Minzhong.", idiomatic: "Now let him be king of Minyue over the lands of Minzhong.\"" },
  { zh: "7帝西都洛陽。", literal: "7. The emperor moved the western capital to Luoyang.", idiomatic: "7. The emperor made Luoyang his western capital." },
  { zh: "8夏，五月，兵皆罷歸家。", literal: "8. In summer, the fifth month, all troops were dismissed to return home.", idiomatic: "8. In summer, the fifth month, all troops were dismissed to return home." },
  { zh: "9詔：「民前或相聚保山澤，不書名數。", literal: "9. An edict: \"Commoners who formerly gathered to hold mountain marshes, not entered in the registers—", idiomatic: "9. An edict: \"Commoners who formerly gathered in the hills and marshes for refuge, not entered in the registers—" },
  { zh: "今天下已定，令各歸其縣，復故爵、田宅；", literal: "now that all under Heaven is settled, order each to return to his county and restore former ranks, fields, and dwellings;", idiomatic: "now that the realm is settled, let each return to his county and restore his former rank, fields, and dwelling;" },
  { zh: "吏以文法教訓辨告，勿笞辱軍吏卒；", literal: "let clerks instruct and explain by written statute; do not lash or insult army officers and soldiers;", idiomatic: "let clerks instruct them by statute and explanation; do not lash or insult soldiers;" },
  { zh: "爵及七大夫以上，皆令食邑，非七大夫已下，皆復其身及戶，勿事。", literal: "those of rank seventh grandee and above—all order food-rents from fiefs; those below seventh grandee—all restore their persons and households, exempt from levies.", idiomatic: "those of rank seventh grandee and above shall receive sustenance from their fiefs; those below seventh grandee shall have their persons and households restored and be exempt from levies.\"" },
  { zh: "10帝置酒洛陽南宮，上曰：「徹侯、諸將毋敢隱朕，皆言其情。", literal: "10. The Emperor set out wine at the Southern Palace in Luoyang. The sovereign said: \"Marquises and generals, do not dare hide anything from Us—each speak his mind.", idiomatic: "10. The Emperor set out wine at the Southern Palace in Luoyang. He said: \"Marquises and generals, do not hide anything from me—each speak plainly." },
  { zh: "吾所以有天下者何？", literal: "Why is it that We possess All under Heaven?", idiomatic: "Why do I possess all under Heaven?" },
  { zh: "項氏之所以失天下者何？", literal: "Why is it that the house of Xiang lost All under Heaven?", idiomatic: "Why did the house of Xiang lose all under Heaven?" },
  { zh: "」高起、王陵對曰：「陛下使人攻城略地，因以與之，與天下同其利；", literal: "\" Gao Qi and Wang Ling replied: \"Your Majesty sends men to attack cities and seize lands and then gives them away, sharing profit with all under Heaven;", idiomatic: "\" Gao Qi and Wang Ling replied: \"Your Majesty sends men to attack cities and seize lands and then gives them away, sharing the profit with all under Heaven;" },
  { zh: "項羽不然，有功者害之，賢者疑之，此其所以失天下也。", literal: "Xiang Yu was not so—he harmed those who had merit and suspected the worthy; this is why he lost All under Heaven.", idiomatic: "Xiang Yu did not. He harmed men of merit and suspected the worthy—that is why he lost all under Heaven." },
  { zh: "」上曰：「公知其一，未知其二。", literal: "\" The sovereign said: \"You gentlemen know one part and do not know the second.", idiomatic: "\" The Emperor said: \"You know one part and not the second." },
  { zh: "夫運籌帷幄之中，決勝千里之外，吾不如子房；", literal: "To plot within the command tent and decide victory a thousand li away—We are not the equal of Zifang;", idiomatic: "To plot within the command tent and decide victory a thousand li away—I am not the equal of Zifang;" },
  { zh: "填國家，撫百姓，給餉饋，不絕糧道，吾不如蕭何；", literal: "to fill the state, comfort the people, supply rations, and keep the grain routes unbroken—We are not the equal of Xiao He;", idiomatic: "to fill the state, comfort the people, supply rations, and keep the grain routes unbroken—I am not the equal of Xiao He;" },
  { zh: "連百萬之眾，戰必勝，攻必取，吾不如韓信。", literal: "to link hosts of a million, win every battle, and take every assault—We are not the equal of Han Xin.", idiomatic: "to command hosts of a million, win every battle, and take every assault—I am not the equal of Han Xin." },
  { zh: "三者皆人傑，吾能用之，此吾所以取天下者也。", literal: "All three are heroes among men; We were able to use them—this is why We took All under Heaven.", idiomatic: "All three are heroes among men, and I was able to use them—that is why I took all under Heaven." },
  { zh: "項羽有一范增而不能用，此所以為我禽也。", literal: "Xiang Yu had one Fan Zeng and could not use him—this is why he was captured by Us.", idiomatic: "Xiang Yu had one Fan Zeng and could not use him—that is why he became my captive." },
  { zh: "」群臣說服。", literal: "\" The assembled ministers were persuaded and submitted.", idiomatic: "\" The assembled ministers were persuaded and convinced." },
  { zh: "韓信至楚，召漂母，賜千金。", literal: "Han Xin reached Chu, summoned the washerwoman, and bestowed a thousand in gold.", idiomatic: "When Han Xin reached Chu he summoned the washerwoman and bestowed a thousand in gold." },
  { zh: "召辱己少年令出胯下者，以為中尉，告諸將相曰：「此壯士也。", literal: "He summoned the youth who had shamed him by making him crawl between his legs and made him Commandant of the Palace Guards, telling the generals and chancellors: \"This is a brave man.", idiomatic: "He summoned the youth who had shamed him by making him crawl between his legs and made him Commandant of the Palace Guards, telling the generals and chancellors: \"This was a brave man." },
  { zh: "方辱我時，我寧不能殺之邪？", literal: "When he shamed me, could I not have killed him?", idiomatic: "When he shamed me, could I not have killed him?" },
  { zh: "殺之無名，故忍而就此。", literal: "To kill him would have brought no renown, so I bore it and came to this.", idiomatic: "To kill him would have brought no renown, so I bore it and rose to this.\"" },
  { zh: "11彭越既受漢封，田橫懼誅，與其徒屬五百餘人入海，居島中。", literal: "11. Peng Yue having already received Han enfeoffment, Tian Heng feared execution. With more than five hundred followers he went to sea and dwelt on an island.", idiomatic: "11. Peng Yue having already received Han enfeoffment, Tian Heng feared execution. With more than five hundred followers he went to sea and dwelt on an island." },
  { zh: "帝以田橫兄弟本定齊地，齊賢者多附焉；", literal: "The Emperor, considering that Tian Heng and his brothers had originally settled Qi and that many worthy men of Qi adhered to them,", idiomatic: "The Emperor considered that Tian Heng and his brothers had originally settled Qi and that many worthy men of Qi still adhered to them;" },
  { zh: "今在海中，不取，後恐為亂。", literal: "now that they were at sea, thought that if they were not taken, they might later become a source of disorder.", idiomatic: "now that they were at sea, he thought that if they were not taken in, they might later stir rebellion." },
  { zh: "乃使使赦橫罪，召之。", literal: "He therefore sent an envoy to pardon Heng's crimes and summon him.", idiomatic: "He sent an envoy to pardon Heng's crimes and summon him." },
  { zh: "橫謝曰：「臣烹陛下之使酈生，今聞其弟商為漢將；", literal: "Heng declined, saying: \"Your servant boiled Your Majesty's envoy Li Yiji; now I hear that his younger brother Shang is a Han general;", idiomatic: "Heng declined: \"Your servant boiled Your Majesty's envoy Li Yiji; now I hear that his younger brother Shang is a Han general;" },
  { zh: "臣恐懼，不敢奉詔，請為庶人，守海島中。", literal: "your servant is afraid and dares not obey the summons. I beg to remain a commoner and guard my island in the sea.", idiomatic: "I am afraid and dare not obey the summons. I beg to remain a commoner and guard my island in the sea." },
  { zh: "」使還報，帝乃詔衛尉酈商曰：「齊王田橫即至，人馬從者敢動搖者，致族夷！", literal: "\" The envoy returned and reported. The Emperor then issued an edict to the Commandant of the Guards Li Shang: \"When the king of Qi Tian Heng arrives, whoever among men, horses, or followers dares to stir trouble—exterminate his clan!", idiomatic: "\" The envoy returned and reported. The Emperor then edicted the Commandant of the Guards Li Shang: \"When the king of Qi Tian Heng arrives, whoever among men, horses, or followers dares to stir trouble—exterminate his entire clan!" },
  { zh: "」乃復使使持節具告以詔商狀，曰：「田橫來，大者王，小者乃侯耳；", literal: "\" He again sent an envoy bearing credentials to inform Heng fully of Shang's situation, saying: \"If Tian Heng comes, at most he will be a king, at least a marquis;", idiomatic: "\" He again sent an envoy bearing credentials to inform Heng fully of Shang's situation: \"If Tian Heng comes, at most he will be a king, at least a marquis;" },
  { zh: "不來，且舉兵加誅焉！", literal: "if he does not come, We shall shortly raise troops to punish him!", idiomatic: "if he does not come, I shall shortly raise troops to punish him!\"" },
  { zh: "橫乃與其客二人乘傳詣洛陽。", literal: "Heng then rode post-horses with two of his retainers and set out for Luoyang.", idiomatic: "Heng then rode post-horses with two retainers and set out for Luoyang." },
  { zh: "未至三十里，至屍鄉廄置。", literal: "Thirty li short of arrival he reached the Yixiang stable post.", idiomatic: "Thirty li short of the city he reached the Yixiang stable post." },
  { zh: "橫謝使者曰：「人臣見天子，當洗沐。", literal: "Heng told the envoy: \"When a subject is to see the Son of Heaven, he should bathe and wash.", idiomatic: "Heng told the envoy: \"When a subject is to see the Son of Heaven, he should bathe and wash.\"" },
  { zh: "」因此留，謂其客曰：「橫始與漢王俱南面稱孤；", literal: "\" He therefore stayed and said to his retainers: \"Heng at first faced south with the King of Han, each calling himself a lone ruler;", idiomatic: "\" He therefore stayed and said to his retainers: \"Heng at first faced south with the King of Han, each calling himself a lone ruler;" },
  { zh: "今漢王為天子，而橫乃為亡虜，北面事之，其恥固已甚矣。", literal: "now the King of Han is Son of Heaven, while Heng is a captive in flight, serving him facing north—the shame is already extreme.", idiomatic: "now the King of Han is Son of Heaven while Heng is a captive in flight, serving him facing north—the shame is already extreme." },
  { zh: "且吾烹人之兄，與其弟並肩而事主，縱彼畏天子之詔不敢動，我獨不愧於心乎?且陛下所以欲見我者，不過欲一見吾面貌耳。", literal: "Moreover, I boiled a man's elder brother and now would serve his master shoulder to shoulder with the younger brother—even if he, fearing the Son of Heaven's edict, dared not stir, would I alone feel no shame in my heart? Moreover, what Your Majesty wishes in seeing me is only to behold my face once.", idiomatic: "Moreover, I boiled a man's elder brother and would now serve his master shoulder to shoulder with the younger—even if he, fearing the Son of Heaven's edict, dared not stir, would I alone feel no shame? And what Your Majesty wishes in seeing me is only to behold my face once." },
  { zh: "今斬吾頭，馳三十里間，形容尚未能敗，猶可觀也。", literal: "If you cut off my head now and gallop the thirty li, my features will not yet have spoiled—it may still be viewed.", idiomatic: "Cut off my head now and gallop the thirty li—my features will not yet have spoiled. It may still be viewed." },
  { zh: "」遂自剄，令客奉其頭，從使者馳奏之。", literal: "\" He thereupon cut his own throat, had a retainer bear his head, and with the envoy galloped to report.", idiomatic: "\" He cut his own throat, had a retainer bear his head, and galloped with the envoy to report." },
  { zh: "帝曰：「嗟乎！", literal: "The Emperor said: \"Alas!", idiomatic: "The Emperor said: \"Alas!" },
  { zh: "起自布衣，兄弟三人更王，豈不賢哉?」為之流涕，而拜其二客為都尉；", literal: "Rising from common cloth, three brothers in succession became kings—is this not worthy?\" He wept for him and appointed his two retainers Commandants;", idiomatic: "Rising from common cloth, three brothers in succession became kings—is that not worthy?\" He wept for him and appointed his two retainers Commandants;" },
  { zh: "發卒二千人，以王者禮葬之。", literal: "he dispatched two thousand soldiers to bury him with the rites of a king.", idiomatic: "he dispatched two thousand soldiers to bury him with the rites of a king." },
  { zh: "既葬，二客穿其塚傍孔，皆自剄，下從之。", literal: "After the burial, the two retainers bored holes beside the tomb, all cut their throats, and went down to follow him.", idiomatic: "After the burial the two retainers bored holes beside the tomb, cut their throats, and went down to follow him." },
  { zh: "帝聞之，大驚。", literal: "The Emperor heard of it and was greatly alarmed.", idiomatic: "The Emperor heard of it and was greatly alarmed." },
  { zh: "以橫客皆賢，餘五百人尚在海中，使使召之；", literal: "Considering Heng's retainers all worthy, and that more than five hundred men still remained at sea, he sent envoys to summon them;", idiomatic: "Considering Heng's retainers all worthy, and that more than five hundred men still remained at sea, he sent envoys to summon them;" },
  { zh: "至，則聞田死，亦皆自殺。", literal: "when they arrived and heard that Tian was dead, they too all killed themselves.", idiomatic: "when they arrived and heard that Tian was dead, they too all killed themselves." },
  { zh: "12初，楚人季布為項籍將，數窘辱帝。", literal: "12. Earlier, the man of Chu Ji Bu had been a general of Xiang Ji and several times cornered and shamed the Emperor.", idiomatic: "12. Earlier, Ji Bu of Chu had been a general of Xiang Yu and several times cornered and shamed the Emperor." },
  { zh: "項籍滅，帝購求布千金；", literal: "When Xiang Ji perished, the Emperor offered a thousand in gold for Bu;", idiomatic: "When Xiang Yu perished, the Emperor offered a thousand in gold for Bu;" },
  { zh: "敢有舍匿，罪三族。", literal: "whoever dared shelter or hide him would be punished with extinction of three clans.", idiomatic: "whoever dared shelter or hide him would suffer extinction of three clans." },
  { zh: "布乃髡鉗為奴，自賣於朱家。", literal: "Bu then had his head shaved and wore a cangue as a slave and sold himself to Zhu Jia.", idiomatic: "Bu had his head shaved, wore a cangue as a slave, and sold himself to Zhu Jia." },
  { zh: "朱家心知其季布也，買置田舍，身之洛陽見籐公，說曰：「季布何罪？", literal: "Zhu Jia knew in his heart that this was Ji Bu. He bought him and placed him in a farmstead, then went in person to Luoyang to see the Duke of Teng and urged: \"What crime has Ji Bu committed?", idiomatic: "Zhu Jia knew in his heart that this was Ji Bu. He bought him and placed him on a farm, then went in person to Luoyang to see the Duke of Teng and urged: \"What crime has Ji Bu committed?" },
  { zh: "臣各為其主用，職耳；", literal: "Each subject serves his own lord—that is duty alone;", idiomatic: "Each man serves his own lord—that is duty alone;" },
  { zh: "項氏臣豈可盡誅邪？", literal: "can all the subjects of the house of Xiang be executed?", idiomatic: "can all the subjects of the house of Xiang be executed?" },
  { zh: "今上始得天下，而以私怨求一人，何示不廣也。", literal: "Now Your Majesty has just won All under Heaven yet seeks one man from private enmity—what narrowness does this display?", idiomatic: "Your Majesty has just won all under Heaven yet seeks one man from private enmity—what narrowness does this display?" },
  { zh: "且以季布之賢，漢求之急，此不北走胡，南走越耳。", literal: "Moreover, given Ji Bu's worth, if Han seeks him urgently, will he not flee north to the Hu or south to Yue?", idiomatic: "Moreover, given Ji Bu's worth, if Han seeks him urgently, will he not flee north to the Hu or south to Yue?" },
  { zh: "夫忌壯士以資敵國，此伍子胥所以鞭荊平之墓也。", literal: "To grudge a brave man and thereby strengthen an enemy state—this is why Wu Zixu flogged the tomb of King Ping of Chu.", idiomatic: "To grudge a brave man and thereby strengthen an enemy state—that is why Wu Zixu flogged the tomb of King Ping of Chu." },
  { zh: "君何不從容為上言之！", literal: "Why do you not speak of this at leisure to Your Majesty!", idiomatic: "Why do you not speak of this at leisure to Your Majesty?\"" },
  { zh: "」滕公待間言於上，如朱家指。", literal: "\" The Duke of Teng waited for an opening and spoke to the sovereign as Zhu Jia had indicated.", idiomatic: "\" The Duke of Teng waited for an opening and spoke to the Emperor as Zhu Jia had indicated." },
  { zh: "上乃赦布，召拜郎中，朱家遂不復見之。", literal: "The sovereign thereupon pardoned Bu, summoned him, and appointed him Gentleman of the Palace; Zhu Jia never saw him again.", idiomatic: "The Emperor pardoned Bu, summoned him, and appointed him Gentleman of the Palace; Zhu Jia never saw him again." },
  { zh: "布母弟丁公，亦為項羽將，逐窘帝彭城西。", literal: "Bu's mother's younger brother Lord Ding had also been a general of Xiang Yu and had pursued and cornered the Emperor west of Pengcheng.", idiomatic: "Bu's mother's younger brother Lord Ding had also been a general of Xiang Yu and had pursued and cornered the Emperor west of Pengcheng." },
  { zh: "短兵接，帝急，顧謂丁公曰：「兩賢相厄哉！", literal: "With close weapons engaged, the Emperor was in peril and turned to Lord Ding, saying: \"Two worthy men corner each other!", idiomatic: "With close weapons engaged, the Emperor was in peril and turned to Lord Ding: \"Two worthy men corner each other!\"" },
  { zh: "」丁公引兵而還。", literal: "\" Lord Ding led his troops back.", idiomatic: "\" Lord Ding led his troops back." },
  { zh: "及項王滅，丁公謁見。", literal: "When the King of Xiang perished, Lord Ding came to audience.", idiomatic: "When Xiang Yu perished, Lord Ding came to audience." },
  { zh: "帝以丁公徇軍中，曰：「丁公為項王臣不忠，使項王失天下者也。", literal: "The Emperor displayed Lord Ding before the army, saying: \"Lord Ding, as a subject of the King of Xiang, was disloyal and caused the King of Xiang to lose All under Heaven.", idiomatic: "The Emperor displayed Lord Ding before the army: \"Lord Ding, as Xiang Yu's subject, was disloyal and caused Xiang Yu to lose all under Heaven." },
  { zh: "」遂斬之，曰：「使後為人臣無效丁公也。", literal: "\" He thereupon beheaded him, saying: \"Let later subjects not imitate Lord Ding.", idiomatic: "\" He beheaded him, saying: \"Let later subjects not imitate Lord Ding.\"" },
  { zh: "::臣光曰：高祖起豐、沛以來，罔羅豪桀，招亡納叛，亦已多矣。", literal: ":: Your servant Guang says: From the time the High Ancestor rose in Feng and Pei, he had netted heroes and champions and received the fugitive and the rebel—already very many indeed.", idiomatic: ":: Your servant Guang says: From the time the High Ancestor rose in Feng and Pei, he had netted heroes and received fugitives and rebels—already very many indeed." },
  { zh: "及即帝位，而丁公獨以不忠受戮，何哉？", literal: "Yet when he took the imperial throne, Lord Ding alone was put to death for disloyalty—why?", idiomatic: "Yet when he took the throne, Lord Ding alone was put to death for disloyalty—why?" },
  { zh: "夫進取之與守成，其勢不同。", literal: "Seizing power and preserving what is won—their circumstances differ.", idiomatic: "Seizing power and preserving what is won—their circumstances differ." },
  { zh: "當群雄角逐之際，民無定主，來者受之，固其宜也。", literal: "In the age when many heroes contended, the people had no fixed lord; to receive whoever came was indeed fitting.", idiomatic: "When many heroes contended, the people had no fixed lord; to receive whoever came was indeed fitting." },
  { zh: "及貴為天子，四海之內，無不為臣；", literal: "When one is exalted as Son of Heaven, within the four seas none is not a subject;", idiomatic: "When one is exalted as Son of Heaven, within the four seas none is not a subject;" },
  { zh: "苟不明禮義以示之，使為臣者，人懷貳心以徼大利，則國家其能久安乎？", literal: "if one does not make clear ritual and righteousness to show them, so that subjects each harbor a divided heart to seek great gain, how can the state long endure in peace?", idiomatic: "if one does not make ritual and righteousness clear, so that every subject harbors a divided heart to seek great gain, how can the state long endure?" },
  { zh: "是故斷以大義，使天下曉然皆知為臣不忠者無所自容；", literal: "Therefore he judged by great righteousness, so that all under Heaven clearly knew that disloyal subjects had nowhere to hide themselves;", idiomatic: "Therefore he judged by great righteousness, so that all under Heaven clearly knew disloyal subjects had nowhere to hide;" },
  { zh: "而懷私結恩者，雖至於活己，猶以義不與也。", literal: "and those who cherished private favor and bound personal kindness, though it reached the point of saving their own lives, still found righteousness would not grant them acceptance.", idiomatic: "and those who cherished private favor and bound personal kindness, though it saved their lives, still found righteousness would not accept them." },
  { zh: "戮一人而千萬人懼，其慮事豈不深且遠哉？", literal: "To punish one man and make ten thousand men fear—was his consideration of affairs not deep and far-reaching?", idiomatic: "To punish one man and make ten thousand fear—was his consideration not deep and far-reaching?" },
  { zh: "子孫享有天祿四百餘年，宜矣！", literal: "That his descendants enjoyed Heaven's blessing for more than four hundred years was fitting indeed!", idiomatic: "That his descendants enjoyed Heaven's blessing for more than four hundred years was fitting indeed!" },
  { zh: "13齊人婁敬戍隴西，過洛陽，脫輓輅，衣羊裘，因齊人虞將軍求見上。", literal: "13. Lou Jing of Qi, garrisoning Longxi, passed through Luoyang, cast off his cart-pole and traces, wore a sheepskin coat, and through General Yu of Qi sought audience with the sovereign.", idiomatic: "13. Lou Jing of Qi, garrisoning Longxi, passed through Luoyang, cast off his cart-pole and traces, wore a sheepskin coat, and through General Yu of Qi sought audience with the Emperor." },
  { zh: "虞將軍欲與之鮮衣，婁敬曰：「臣衣帛，衣帛見；", literal: "General Yu wished to give him fine clothes. Lou Jing said: \"Your servant in silk goes clothed in silk to audience;", idiomatic: "General Yu wished to give him fine clothes. Lou Jing said: \"Your servant in silk goes clothed in silk to audience;" },
  { zh: "衣褐，衣褐見，終不敢易衣。", literal: "in coarse cloth, in coarse cloth to audience—I dare not at the end change clothes.", idiomatic: "in coarse cloth, in coarse cloth to audience—I dare not change clothes at the end.\"" },
  { zh: "」於是虞將軍入言上，上召見，問之。", literal: "\" Thereupon General Yu entered and spoke to the sovereign; the sovereign summoned him to audience and questioned him.", idiomatic: "\" Thereupon General Yu entered and spoke to the Emperor; the Emperor summoned him to audience and questioned him." },
  { zh: "婁敬曰：「陛下都洛陽，豈欲與周室比隆哉？", literal: "Lou Jing said: \"Your Majesty is establishing the capital at Luoyang—do you wish to rival the Zhou house in splendor?", idiomatic: "Lou Jing said: \"Your Majesty is establishing the capital at Luoyang—do you wish to rival the Zhou in splendor?\"" },
  { zh: "」上曰：「然。", literal: "\" The sovereign said: \"Indeed.", idiomatic: "\" The Emperor said: \"Indeed.\"" },
  { zh: "」婁敬曰：「陛下取天下與周異。", literal: "\" Lou Jing said: \"Your Majesty won All under Heaven differently from Zhou.", idiomatic: "\" Lou Jing said: \"Your Majesty won all under Heaven differently from Zhou." },
  { zh: "周之先，自後稷封邰，積德累善，十有餘世，至於太王、王季、文王、武王而諸侯自歸之，遂滅殷為天子。", literal: "Zhou's forebears, from the time Hou Ji was enfeoffed at Tai, accumulated virtue and goodness for more than ten generations, until King Tai, King Ji, King Wen, and King Wu, when the feudal lords came to them of themselves, and they thereupon destroyed Yin and became Sons of Heaven.", idiomatic: "Zhou's forebears, from the time Hou Ji was enfeoffed at Tai, accumulated virtue for more than ten generations, until Kings Tai, Ji, Wen, and Wu, when the feudal lords came of themselves, and they destroyed Yin and became Sons of Heaven." },
  { zh: "及成王即位，周公相焉，乃營洛邑，以為此天下之中也，諸侯四方納貢職，道里均矣。", literal: "When King Cheng took the throne, the Duke of Zhou assisted him and then built Luoyang, taking this as the center of All under Heaven, so that the feudal lords from the four quarters brought tribute and duties and the roads and distances were equal.", idiomatic: "When King Cheng took the throne, the Duke of Zhou assisted him and built Luoyang, taking it as the center of all under Heaven, so that feudal lords from the four quarters brought tribute and the roads and distances were equal." },
  { zh: "有德則易以王，無德則易以亡。", literal: "With virtue it was easy to become king; without virtue it was easy to perish.", idiomatic: "With virtue it was easy to become king; without virtue it was easy to perish." },
  { zh: "故周之盛時，天下和洽，諸侯、四夷莫不賓服，效其貢職。", literal: "Therefore in Zhou's age of splendor, All under Heaven was harmonious; feudal lords and the four barbarians none failed to attend in submission and present their tribute and duties.", idiomatic: "Therefore in Zhou's age of splendor all under Heaven was harmonious; feudal lords and the four barbarians all attended in submission and presented tribute." },
  { zh: "及其衰也，天下莫朝，周不能制也；", literal: "When it declined, none in All under Heaven came to court, and Zhou could not control them;", idiomatic: "When it declined, none in all under Heaven came to court, and Zhou could not control them;" },
  { zh: "非唯其德薄也，形勢弱也。", literal: "it was not only that its virtue was thin—its strategic position was weak.", idiomatic: "it was not only that its virtue was thin—its strategic position was weak." },
  { zh: "今陛下起豐、沛，卷蜀、漢，定三秦，與項羽戰滎陽、成皋之間，大戰七十，小戰四十；", literal: "Now Your Majesty rose in Feng and Pei, rolled up Shu and Han, settled the Three Qins, and fought Xiang Yu between Yingyang and Chenggao—seventy great battles and forty lesser ones;", idiomatic: "Now Your Majesty rose in Feng and Pei, rolled up Shu and Han, settled the Three Qins, and fought Xiang Yu between Yingyang and Chenggao—seventy great battles and forty lesser ones;" },
  { zh: "使天下之民，肝腦塗地，父子暴骨中野，不可勝數，哭泣之聲未絕，傷夷者未起；", literal: "causing the people of All under Heaven to smear liver and brain on the ground, fathers and sons left bones exposed in the wilds beyond counting, the sound of weeping not yet ended, the wounded not yet risen;", idiomatic: "causing the people to smear liver and brain on the ground, fathers and sons left bones in the wilds beyond counting, weeping not yet ended, the wounded not yet risen;" },
  { zh: "而欲比隆於成、康之時，臣竊以為不侔也。", literal: "yet you wish to rival the age of Cheng and Kang—I venture to think this does not match.", idiomatic: "yet you wish to rival the age of Cheng and Kang—I venture to think this does not match." },
  { zh: "且夫秦地被山帶河，四塞以為固，卒然有急，百萬之眾可立具也。", literal: "Moreover, Qin's territory is girded by mountains and rivers, fortified on four sides; if suddenly there is urgency, a host of a million can be raised at once.", idiomatic: "Moreover, Qin's territory is girded by mountains and rivers, fortified on four sides; if urgency comes suddenly, a host of a million can be raised at once." },
  { zh: "因秦之故，資甚美膏腴之地，此所謂天府者也。", literal: "Relying on Qin's old foundations, it enjoys very fine fertile lands—this is what is called the Storehouse of Heaven.", idiomatic: "Relying on Qin's old foundations, it enjoys very fine fertile lands—this is what men call the Storehouse of Heaven." },
  { zh: "陛下入關而都之，山東雖亂，秦之故地可全而有也。", literal: "If Your Majesty enters the passes and makes it your capital, though the lands east of the mountains be in disorder, Qin's old territory can be held whole.", idiomatic: "If Your Majesty enters the passes and makes it your capital, though the lands east of the mountains be in disorder, Qin's old territory can be held whole." },
  { zh: "夫與人斗，不搤其亢，拊其背，未能全其勝也。", literal: "In fighting a man, if one does not seize his throat and strike his back, one cannot fully secure victory.", idiomatic: "In fighting a man, if one does not seize his throat and strike his back, one cannot fully secure victory." },
  { zh: "今陛下案秦之故地，此亦扼天下之亢而拊其背也。", literal: "Now if Your Majesty settles in Qin's old territory, this too is seizing the throat of All under Heaven and striking its back.", idiomatic: "Now if Your Majesty settles in Qin's old territory, this too is seizing the throat of all under Heaven and striking its back." },
  { zh: "」帝問群臣，群臣皆山東人，爭言：「周王數百年，秦二世即亡。", literal: "\" The Emperor questioned the assembled ministers. The ministers were all men from east of the mountains and contended: \"The house of Zhou reigned for several hundred years; Qin perished in the second generation.", idiomatic: "\" The Emperor questioned the assembled ministers. They were all men from east of the mountains and contended: \"The house of Zhou reigned for several hundred years; Qin perished in the second generation." },
  { zh: "洛陽東有成皋，西有殽、澠，倍河，鄉伊、洛，其固亦足恃也。", literal: "East of Luoyang there is Chenggao; west are Xiao and Mian; it backs the river and faces Yi and Luo—its defenses too are sufficient to rely upon.", idiomatic: "East of Luoyang there is Chenggao; west are Xiao and Mian; it backs the river and faces Yi and Luo—its defenses too are sufficient to rely upon.\"" },
  { zh: "」上問張良。", literal: "\" The sovereign asked Zhang Liang.", idiomatic: "\" The Emperor asked Zhang Liang." },
  { zh: "良曰：「洛陽雖有此固，其中小不過數百里，田地薄，四面受敵，此非用武之國也。", literal: "Liang said: \"Though Luoyang has these defenses, within it is small—no more than several hundred li; the fields are thin; it receives enemies on four sides—this is not a state for wielding arms.", idiomatic: "Liang said: \"Though Luoyang has these defenses, within it is small—no more than several hundred li; the fields are thin; it receives enemies on four sides—this is not a state for wielding arms." },
  { zh: "關中左殽、函，右隴、蜀，沃野千里。", literal: "Within the passes, to the left are Xiao and Han, to the right Long and Shu; a thousand li of rich fields.", idiomatic: "Within the passes, to the left are Xiao and Han, to the right Long and Shu—a thousand li of rich fields." },
  { zh: "南有巴、蜀之饒，北有胡苑之利。", literal: "South are the riches of Ba and Shu; north the profit of the Hu pastures.", idiomatic: "South are the riches of Ba and Shu; north the profit of the Hu pastures." },
  { zh: "阻三面而守，獨以一面東制諸侯；", literal: "It blocks three sides and holds them; with one side alone it controls the feudal lords to the east;", idiomatic: "It blocks three sides and holds them; with one side alone it controls the feudal lords to the east;" },
  { zh: "諸侯安定，河、渭漕輓天下，西給京師；", literal: "when the feudal lords are settled, the Yellow and Wei rivers transport grain from all under Heaven west to supply the capital;", idiomatic: "when the feudal lords are settled, the Yellow and Wei transport grain from all under Heaven west to supply the capital;" },
  { zh: "諸侯有變，順流而下，足以委輸。", literal: "when the feudal lords change, going downstream with the current suffices to pour forth supplies.", idiomatic: "when the feudal lords rebel, going downstream with the current suffices to pour forth supplies." },
  { zh: "此所謂金城千里，天府之國也。", literal: "This is what is called a metal wall for a thousand li, a state of the Storehouse of Heaven.", idiomatic: "This is what men call a metal wall for a thousand li, the Storehouse of Heaven." },
  { zh: "婁敬說是也。", literal: "Lou Jing's argument was correct.", idiomatic: "The Emperor accepted Lou Jing's counsel." },
  { zh: "」上即日車駕西，都長安。", literal: "\" That very day the sovereign drove his chariot west and made Chang'an his capital.", idiomatic: "\" That very day the Emperor drove west and established his capital at Chang'an." },
  { zh: "拜婁敬為郎中，號曰奉春君，賜姓劉氏。", literal: "He appointed Lou Jing Gentleman-of-the-Palace, styled him Lord Fengchun, and granted the surname Liu.", idiomatic: "He appointed Lou Jing gentleman-of-the-palace, titled him Lord Fengchun, and gave him the Liu surname." },
  { zh: "14張良素多病，從上入關，即道引，不食穀，杜門不出，曰：「家世相韓，及韓滅，不愛萬金之資，為韓報讎強秦，天下振動。", literal: "14. Zhang Liang had long been ill; following the sovereign into the passes, he then practiced guidance of the Way, ate no grain, shut his gate and did not go out, saying: \"My family for generations had served Han as ministers; when Han was destroyed I did not begrudge resources worth ten thousand in gold, but sought vengeance for Han against mighty Qin, and all under Heaven was shaken.", idiomatic: "14. Zhang Liang had long been ill; following the Emperor into the passes, he then practiced the Way, ate no grain, shut his gate and did not go out, saying: \"My family for generations had served Han as ministers; when Han was destroyed I did not begrudge ten thousand in gold, but sought vengeance for Han against mighty Qin, and the realm was shaken." },
  { zh: "今以三寸舌為帝者師，封萬戶侯，此布衣之極，於良足矣。", literal: "Now with a three-inch tongue I have become teacher to the emperor, enfeoffed marquis of ten thousand households—this is the utmost for a cloth-robed man; for Liang it is enough.", idiomatic: "Now with a three-inch tongue I have become the emperor's teacher and been enfeoffed marquis of ten thousand households—this is the utmost for a commoner; for Liang it is enough." },
  { zh: "願棄人間事，欲從赤松子游耳。", literal: "I wish to abandon human affairs and roam with Master Red Pine.\"", idiomatic: "I wish to leave human affairs behind and wander with Master Red Pine.\"" },
  { zh: "::臣光曰：夫生之有死，譬猶夜旦之必然；", literal: ":: Your servant Guang says: That life has death is like night and dawn—inevitably so;", idiomatic: ":: Your servant Guang says: Life and death are as certain as night giving way to dawn;" },
  { zh: "自古及今，固未嘗有超然而獨存者也。", literal: "from antiquity to the present, there has never been one who transcended and endured alone.", idiomatic: "from antiquity to the present, none has ever transcended death and endured alone." },
  { zh: "以子房之明辨達理，足以知神仙之為虛詭矣；", literal: "By Zifang's clear discernment and grasp of principle, he was fully able to know that immortals and spirits are empty deceit;", idiomatic: "By Zifang's insight, he was fully able to see that talk of immortals is empty fraud;" },
  { zh: "然其欲從赤松子游者，其智可知也。", literal: "yet that he wished to roam with Master Red Pine—his wisdom may be understood.", idiomatic: "yet that he professed to roam with Master Red Pine shows his wisdom." },
  { zh: "夫功名之際，人臣之所難處。", literal: "At the moment of merit and fame, it is what ministers find hard to dwell in.", idiomatic: "At the height of merit and fame, ministers find it hardest to stand firm." },
  { zh: "如高帝所稱者，三傑而已。", literal: "Of those the High Sovereign praised, only three outstanding men.", idiomatic: "Only the three heroes whom the High Sovereign named." },
  { zh: "淮陰誅夷，蕭何繫獄，非以履盛滿而不止耶！", literal: "Huaiyin was executed and extinguished, Xiao He was bound in prison—is it not because they trod the full and did not stop?", idiomatic: "Huaiyin was executed to extinction and Xiao He was thrown into prison—is it not because they kept their cups full and would not stop?" },
  { zh: "故子房托於神仙，遺棄人間，等功名於外物，置榮利而不顧，所謂明哲保身者，子房有焉。", literal: "Therefore Zifang entrusted himself to immortals, abandoned human affairs, made merit and fame equal to external things, set glory and profit aside without regard—the so-called preserving one's wisdom and body—Zifang had it.", idiomatic: "Therefore Zifang entrusted himself to immortals, abandoned human affairs, treated merit and fame as external things, and set glory and profit aside—the so-called preserving one's wisdom and body; Zifang had it." },
  { zh: "15六月，壬辰，大赦天下。", literal: "15. In the sixth month, on renchen, a general amnesty was proclaimed for all under Heaven.", idiomatic: "15. In the sixth month, on renchen, a general amnesty was proclaimed for the realm." },
  { zh: "16秋，七月，燕王臧荼反；", literal: "16. In autumn, the seventh month, Zang Tu, King of Yan, rebelled;", idiomatic: "16. In autumn, the seventh month, King Zang Tu of Yan rebelled;" },
  { zh: "上自將征之。", literal: "the sovereign personally led troops to campaign against him.", idiomatic: "the Emperor personally led troops against him." },
  { zh: "17趙景王耳、長沙文王芮皆薨。", literal: "17. King Jing of Zhao, Er, and King Wen of Changsha, Rui, both died.", idiomatic: "17. King Jing of Zhao, Er, and King Wen of Changsha, Rui, both passed away." },
  { zh: "18九月，虜藏荼。", literal: "18. In the ninth month, Zang Tu was captured.", idiomatic: "18. In the ninth month, Zang Tu was taken prisoner." },
  { zh: "壬子，立太尉長安侯盧綰為燕王。", literal: "On renzi, Grand Marshal Lu Wan, Marquis of Chang'an, was established as King of Yan.", idiomatic: "On renzi, Grand Marshal Lu Wan, Marquis of Chang'an, was made King of Yan." },
  { zh: "綰家與上同里，綰生又與上同日；", literal: "Wan's family had been in the same neighborhood as the sovereign's, and Wan was born on the same day as the sovereign;", idiomatic: "Wan's family had lived in the same neighborhood as the Emperor's, and Wan was born on the same day;" },
  { zh: "上寵幸綰，群臣莫敢望，故特王之。", literal: "the sovereign favored Wan—and none among the ministers dared compare—so he was made king as a special mark of favor.", idiomatic: "the Emperor favored Wan beyond what any minister dared expect, so he was made king as a special mark of favor." },
  { zh: "19項羽故將利幾反，上自擊破之。", literal: "19. Li Ji, a former general of Xiang Yu, rebelled; the sovereign himself attacked and defeated him.", idiomatic: "19. Li Ji, a former general of Xiang Yu, rebelled; the Emperor himself attacked and defeated him." },
  { zh: "20後九月，治長樂宮。", literal: "20. In the intercalary ninth month, the Everlasting Joy Palace was built.", idiomatic: "20. In the intercalary ninth month, work began on the Everlasting Joy Palace." },
  { zh: "21項王將鐘離昧，素與楚王信善。", literal: "21. Zhonglimo, a general of the King of Xiang, had long been on good terms with King Xin of Chu.", idiomatic: "21. Zhonglimo, a general of the King of Xiang, had long been close to King Xin of Chu." },
  { zh: "項王死後，亡歸信。", literal: "After the King of Xiang died, he fled into hiding and returned to Xin.", idiomatic: "After the King of Xiang died, he went into hiding and rejoined Xin." },
  { zh: "漢王怨昧，聞其在楚，詔楚捕昧。", literal: "The King of Han bore a grudge against Mo; hearing he was in Chu, he ordered Chu to arrest Mo.", idiomatic: "The sovereign bore a grudge against Mo; hearing he was in Chu, he ordered Chu to arrest him." },
  { zh: "信初之國，行縣邑，陳兵出入。", literal: "When Xin first went to his state, he traveled through counties and districts with soldiers arrayed at his comings and goings.", idiomatic: "When Xin first went to his kingdom, he toured the counties with armed escorts at every coming and going." },
  { zh: "1冬，十月，人有上書告楚王信反者。", literal: "1. In winter, the tenth month, someone submitted a memorial denouncing King Xin of Chu for rebellion.", idiomatic: "1. In winter, the tenth month, someone submitted a memorial accusing King Xin of Chu of rebellion." },
  { zh: "帝以問諸將，皆曰：「亟發兵，坑豎子耳！", literal: "The Emperor asked the generals; all said: \"Hurry to send troops and bury the brat alive!", idiomatic: "The Emperor asked the generals; all said: \"Send troops at once and bury the brat alive!" },
  { zh: "」帝默然。", literal: "\" The Emperor was silent.", idiomatic: "\" The Emperor said nothing." },
  { zh: "又問陳平。", literal: "He again asked Chen Ping.", idiomatic: "He turned and asked Chen Ping." },
  { zh: "陳平曰：「人上書言信反，信知之乎？", literal: "Chen Ping said: \"Someone submitted a memorial saying Xin rebels—does Xin know of it?", idiomatic: "Chen Ping said: \"Someone has accused Xin of rebellion—does Xin know of it?" },
  { zh: "」曰：「不知。", literal: "\" He said: \"He does not know.\"", idiomatic: "\" He said: \"He does not.\"" },
  { zh: "」陳平曰：「陛下精兵孰與楚？", literal: "\" Chen Ping said: \"Which are finer, Your Majesty's picked troops or Chu's?", idiomatic: "\" Chen Ping asked: \"Which are finer, Your Majesty's elite troops or Chu's?" },
  { zh: "」上曰：「不能過。", literal: "\" The sovereign said: \"They do not surpass them.\"", idiomatic: "\" The Emperor said: \"They do not.\"" },
  { zh: "」平曰：「陛下諸將，用兵有能過韓信者乎？", literal: "\" Ping said: \"Among Your Majesty's generals, is there any who in employing troops surpasses Han Xin?", idiomatic: "\" Ping said: \"Among Your Majesty's generals, is there any who surpasses Han Xin in command?" },
  { zh: "」上曰：「莫及也。", literal: "\" The sovereign said: \"None can match him.\"", idiomatic: "\" The Emperor said: \"None.\"" },
  { zh: "」平曰：「今兵不如楚精而將不及，舉兵攻之，是趣之戰也，竊為陛下危之。", literal: "\" Ping said: \"Now your troops are not as elite as Chu's and your generals do not compare—if you raise troops to attack, this is to hurry him to battle; your servant privately considers this perilous for Your Majesty.\"", idiomatic: "\" Ping said: \"Your troops are not as elite as Chu's and your generals do not compare—if you attack, you force a fight on his terms; I consider this perilous for Your Majesty.\"" },
  { zh: "」上曰：「為之奈何？", literal: "\" The sovereign said: \"What is to be done about it?", idiomatic: "\" The Emperor said: \"What is to be done?\"" },
  { zh: "」平曰：「古者天子有巡狩，會諸侯。", literal: "\" Ping said: \"In antiquity the Son of Heaven had inspection tours and summoned the feudal lords.", idiomatic: "\" Ping said: \"In antiquity the Son of Heaven toured the realm and summoned the feudal lords." },
  { zh: "陛下第出，偽游雲夢，會諸侯於陳。", literal: "Your Majesty should just go out, feign a tour of Yunmeng, and assemble the feudal lords at Chen.", idiomatic: "Your Majesty need only go out, feign a tour of Yunmeng, and assemble the feudal lords at Chen." },
  { zh: "陳，楚之西界；", literal: "Chen is the western border of Chu;", idiomatic: "Chen lies on Chu's western frontier;" },
  { zh: "信聞天子以好出遊，其勢必無事而郊迎謁；", literal: "Xin, hearing the Son of Heaven loves to go touring, is sure under that momentum to go out to the suburbs without affair and greet and pay respects;", idiomatic: "Xin, hearing the Son of Heaven loves to tour, is sure to go out to the suburbs to greet him;" },
  { zh: "謁而陛下因禽之，此特一力士之事耳。", literal: "when he pays respects Your Majesty can then seize him—this is but the affair of a single strong man.\"", idiomatic: "when he pays respects Your Majesty can seize him—this is but the work of one strong man.\"" },
  { zh: "」帝以為然，乃發使告諸侯會陳，「吾將南遊雲夢。", literal: "\" The Emperor thought it sound and sent envoys to tell the feudal lords to assemble at Chen: \"I shall tour Yunmeng to the south.", idiomatic: "\" The Emperor agreed and sent envoys to summon the feudal lords to Chen: \"I shall tour Yunmeng to the south." },
  { zh: "」上因隨以行。", literal: "\" The sovereign thereupon followed along on the expedition.", idiomatic: "\" The Emperor thereupon set out on the expedition." },
  { zh: "楚王信聞之，自疑懼，不知所為。", literal: "King Xin of Chu, hearing this, became suspicious and afraid, not knowing what to do.", idiomatic: "King Xin of Chu, hearing this, grew suspicious and afraid, not knowing what to do." },
  { zh: "或說信曰：「斬鐘離昧以謁上，上必喜，無患。", literal: "Someone urged Xin, saying: \"Behead Zhonglimo and present yourself to the sovereign—the sovereign is sure to be pleased and you will be without peril.", idiomatic: "Someone urged Xin: \"Behead Zhonglimo and present yourself to the Emperor—he is sure to be pleased and you will be safe." },
  { zh: "」信從之。", literal: "\" Xin followed this advice.", idiomatic: "\" Xin did as he was told." },
  { zh: "十二月，上會諸侯於陳，信持昧首謁上；", literal: "In the twelfth month the sovereign assembled the feudal lords at Chen; Xin came holding Mo's head to pay respects to the sovereign;", idiomatic: "In the twelfth month the Emperor assembled the feudal lords at Chen; Xin came holding Mo's head to pay respects;" },
  { zh: "上令武士縛信，載後車。", literal: "the sovereign ordered warriors to bind Xin and load him on the rear chariot.", idiomatic: "the Emperor ordered warriors to bind Xin and load him on the rear chariot." },
  { zh: "信曰：「果若人言：『狡兔死，走狗烹；", literal: "Xin said: \"It proves as men say: 'When the cunning hare is dead, the running dog is cooked;", idiomatic: "Xin said: \"So the proverb runs: 'When the cunning hare is dead, the running dog is cooked;" },
  { zh: "飛鳥盡，良弓藏；", literal: "when the flying birds are gone, the fine bow is stored away;", idiomatic: "when the birds are gone, the fine bow is put away;" },
  { zh: "敵國破，謀臣亡。", literal: "when the enemy state is broken, the plotting minister perishes.", idiomatic: "when the foe is broken, the plotting minister perishes." },
  { zh: "』天下已定，我固當烹！", literal: "\" All under Heaven is already settled—I ought to be cooked!", idiomatic: "\" The realm is settled—I ought to be cooked!" },
  { zh: "」上曰：「人告公反。", literal: "\" The sovereign said: \"A man denounced you for rebellion.\"", idiomatic: "\" The Emperor said: \"A man denounced you for rebellion.\"" },
  { zh: "」遂械系信以歸，因赦天下。", literal: "\" Thereupon he fettered Xin and took him back, and meanwhile proclaimed a general amnesty.", idiomatic: "\" Thereupon he bound Xin and took him back, and meanwhile proclaimed a general amnesty." },
  { zh: "田肯賀上曰：「陛下得韓信，又治秦中。", literal: "Tian Ken congratulated the sovereign, saying: \"Your Majesty has obtained Han Xin and has also ordered Qin territory.", idiomatic: "Tian Ken congratulated the Emperor: \"Your Majesty has taken Han Xin and now holds Qin territory." },
  { zh: "秦，形勝之國也，帶河阻山，地勢便利；", literal: "Qin is a terrain-dominant state, belted by rivers and blocked by mountains, its topography advantageous;", idiomatic: "Qin is a terrain-dominant state, belted by rivers and blocked by mountains, its ground advantageous;" },
  { zh: "其以下兵於諸侯，譬猶居高屋之上建瓴水也。", literal: "to send troops down upon the feudal lords from it is like pouring water from the rooftop of a high house.", idiomatic: "to send troops down upon the feudal lords from it is like pouring water from a rooftop." },
  { zh: "夫齊，東有琅邪、即墨之饒，南有泰山之固，西有濁河之限，北有勃海之利；", literal: "As for Qi, to the east it has the wealth of Langye and Jimo, to the south the security of Mount Tai, to the west the barrier of the muddy river, to the north the profit of the Bohai;", idiomatic: "As for Qi, east are the riches of Langye and Jimo, south the security of Mount Tai, west the barrier of the muddy river, north the profit of the Bohai;" },
  { zh: "地方二千里，持戟百萬，此東西秦也，非親子弟，莫可使王齊者。", literal: "its territory two thousand li, a million men bearing halberds—this is Qin east and west; unless he is a near kinsman, no one should be made king of Qi.\"", idiomatic: "two thousand li of territory, a million men bearing halberds—this is Qin in the east; unless he is a near kinsman, no one should be made king of Qi.\"" },
  { zh: "」上曰：「善！", literal: "\" The sovereign said: \"Excellent!\"", idiomatic: "\" The Emperor said: \"Excellent!\"" },
  { zh: "」賜金五百斤。", literal: "\" He granted five hundred jin of gold.", idiomatic: "\" He rewarded him with five hundred jin of gold." },
  { zh: "上還，至洛陽，赦韓信，封為淮陰侯。", literal: "The sovereign returned; reaching Luoyang he pardoned Han Xin and enfeoffed him as Marquis of Huaiyin.", idiomatic: "On the return, reaching Luoyang, he pardoned Han Xin and enfeoffed him as Marquis of Huaiyin." },
  { zh: "信知漢王畏惡其能，多稱病，不朝從；", literal: "Xin knew the King of Han feared and hated his ability; he often pleaded illness and would not attend court or follow;", idiomatic: "Xin knew the sovereign feared and hated his ability; he often pleaded illness and would not attend court;" },
  { zh: "居常鞅鞅，羞與絳、灌等列。", literal: "dwelling day to day discontent, ashamed to be ranked with Jiang and Guan and the like.", idiomatic: "he lived day to day discontent, ashamed to be ranked with Jiang and Guan and the like." },
  { zh: "嘗過樊將軍噲，噲跪拜送迎，言稱臣，曰：「大王乃肯臨臣！", literal: "Once, passing General Fan Kuai's residence, Kuai knelt in worship coming and going, speaking as subject, saying: \"The great king would deign to visit your servant!", idiomatic: "Once, passing General Fan Kuai's residence, Kuai knelt in worship coming and going and said as a subject: \"The great king would deign to visit your servant!" },
  { zh: "」信出門，笑曰：「生乃與噲等為伍！", literal: "\" Xin went out the gate and laughed, saying: \"Truly I am made of a piece with Kuai and such!", idiomatic: "\" Xin went out the gate and laughed: \"Truly I am made of a piece with Kuai and such!" },
  { zh: "上嘗從容與信言諸將能將兵多少。", literal: "The sovereign once at ease discussed with Xin how many troops each general could command.", idiomatic: "The Emperor once at ease asked Xin how many troops each general could command." },
  { zh: "上問曰：「如我能將幾何？", literal: "The sovereign asked, saying: \"How many could I command, say?", idiomatic: "The Emperor asked: \"How many could I command?" },
  { zh: "」信曰：「陛下不過能將十萬。", literal: "\" Xin said: \"Your Majesty could command no more than a hundred thousand.\"", idiomatic: "\" Xin said: \"Your Majesty, no more than a hundred thousand.\"" },
  { zh: "」上曰：「於君何如？", literal: "\" The sovereign said: \"And you—how about you?", idiomatic: "\" The Emperor said: \"And you?\"" },
  { zh: "」曰：「臣多多而益善耳。", literal: "\" He said: \"Your servant—more, more, and yet more is better.\"", idiomatic: "\" He said: \"I—the more the better.\"" },
  { zh: "」上笑曰：「多多益善，何為為我禽？", literal: "\" The sovereign laughed, saying: \"More is better—why then were you seized for me?", idiomatic: "\" The Emperor laughed: \"The more the better—why then were you seized for me?" },
  { zh: "」信曰：「陛下不能將兵而善將將，此乃信之所以為陛下禽也。", literal: "\" Xin said: \"Your Majesty cannot command troops but excels at commanding generals—this is why Xin was seized for Your Majesty.", idiomatic: "\" Xin said: \"Your Majesty cannot command troops but excels at commanding generals—that is why I was seized for you." },
  { zh: "且陛下，所謂天授，非人力也。", literal: "Moreover Your Majesty is what is called Heaven-bestowed—it is not human effort.\"", idiomatic: "Moreover Your Majesty is what men call Heaven-bestowed—it is not human effort.\"" },
  { zh: "----2甲申，始剖符封諸功臣為徹侯。", literal: "----2 On jiashen, tally-splitting first enfeoffed the meritorious ministers as full marquises.", idiomatic: "----2 On jiashen, the sovereign first split tallies and enfeoffed the meritorious ministers as full marquises." },
  { zh: "蕭何封酇侯，所食邑獨多。", literal: "Xiao He was enfeoffed Marquis of Zan, his fief-rents alone were many.", idiomatic: "Xiao He was enfeoffed Marquis of Zan with a fief larger than any other." },
  { zh: "功臣皆曰：「臣等身被堅執銳，多者百餘戰，小者數十合。", literal: "The meritorious ministers all said: \"We wore armor and wielded sharp weapons—many of us over a hundred battles, the few dozens of encounters.", idiomatic: "The meritorious ministers all said: \"We wore armor and wielded sharp weapons—some of us over a hundred battles, the few dozens of engagements." },
  { zh: "今蕭何未嘗有汗馬之勞，徒持文墨議論，顧反居臣等上，何也？", literal: "Now Xiao He never had the toil of sweating horses, but merely held ink and brush for discussion—yet he is set above us; why?", idiomatic: "Now Xiao He never toiled in the saddle but merely held ink and brush—yet he ranks above us. Why?" },
  { zh: "」帝曰：「諸君知獵乎？", literal: "\" The Emperor said: \"Do you lords know hunting?", idiomatic: "\" The Emperor said: \"Do you know hunting?" },
  { zh: "夫獵，追殺獸兔者，狗也；", literal: "In hunting, those who chase and kill beasts and hares are the dogs;", idiomatic: "In the hunt, those who chase and kill the game are the dogs;" },
  { zh: "而發縱指示獸處者，人也。", literal: "but those who release the hounds and point out where the beasts are—the man.", idiomatic: "but those who slip the hounds and show where the game lies—the man." },
  { zh: "今諸君徒能得走獸耳，功狗也；", literal: "Now you lords can only obtain running beasts—the merit is the dogs';", idiomatic: "Now you can only catch running beasts—your merit is that of the dogs;" },
  { zh: "至如蕭何，發縱指示，功人也。", literal: "as for Xiao He, releasing and pointing—the man's merit.\"", idiomatic: "as for Xiao He, who slipped the hounds and showed the way—the man's merit.\"" },
  { zh: "」群臣皆不敢言。", literal: "\" The assembled ministers did not dare speak.", idiomatic: "\" The assembled ministers fell silent." },
  { zh: "張良為謀臣，亦無戰鬥功；", literal: "Zhang Liang as plotting minister also had no battle merit;", idiomatic: "Zhang Liang as strategist also had no battle merit;" },
  { zh: "帝使自擇齊三萬戶。", literal: "the Emperor had him choose for himself thirty thousand households in Qi.", idiomatic: "the Emperor let him choose thirty thousand households in Qi for himself." },
  { zh: "良曰：「始，臣起下邳，與上會留，此天以臣授陛下。", literal: "Liang said: \"At the beginning your servant rose from Xiapi and met Your Majesty at Liu—this was Heaven presenting your servant to Your Majesty.", idiomatic: "Liang said: \"At the beginning I rose from Xiapi and met Your Majesty at Liu—Heaven presented me to you." },
  { zh: "陛下用臣計，幸而時中。", literal: "Your Majesty used your servant's plans, and fortunately they hit the moment.", idiomatic: "Your Majesty used my plans, and fortunately they hit the moment." },
  { zh: "臣願封留足矣，不敢當三萬戶。", literal: "Your servant wishes to be enfeoffed at Liu and that suffices; I dare not receive thirty thousand households.\"", idiomatic: "I ask only to be enfeoffed at Liu; I dare not receive thirty thousand households.\"" },
  { zh: "」乃封張良為留侯。", literal: "\" Thereupon Zhang Liang was enfeoffed Marquis of Liu.", idiomatic: "\" Thereupon he enfeoffed Zhang Liang as Marquis of Liu." },
  { zh: "封陳平為戶牖侯。", literal: "Chen Ping was enfeoffed Marquis of Huyu.", idiomatic: "Chen Ping was made Marquis of Huyu." },
  { zh: "平辭曰：「此非臣之功也。", literal: "Ping declined, saying: \"This is not your servant's merit.", idiomatic: "Ping declined: \"This is not my merit." },
  { zh: "」上曰：「吾用先生謀計，戰勝克敵，非功而何？", literal: "\" The sovereign said: \"I used your plans, sir, and won battles and overcame foes—if not merit, what?", idiomatic: "\" The Emperor said: \"I used your plans and won battles—if not merit, what?" },
  { zh: "」平曰：「非魏無知，臣安得進？", literal: "\" Ping said: \"Without Wei Wuzhi, how could your servant have advanced?", idiomatic: "\" Ping said: \"Without Wei Wuzhi, how could I have advanced?" },
  { zh: "」上曰：「若子，可謂不背本矣！", literal: "\" The sovereign said: \"A man like you may be called one who does not betray his roots!", idiomatic: "\" The Emperor said: \"A man like you may be called one who does not betray his roots!" },
  { zh: "」乃復賞魏無知。", literal: "\" Thereupon he again rewarded Wei Wuzhi.", idiomatic: "\" Thereupon he rewarded Wei Wuzhi again." },
  { zh: "----3帝以天下初定，子幼，昆弟少，懲秦孤立而亡，欲大封同姓以填撫天下。", literal: "----3 The Emperor, considering that the realm was newly settled, his sons young, and his brothers few, took warning from Qin's perishing through isolation and wished to enfeoff kinsmen of the same surname on a large scale to fill and pacify the realm.", idiomatic: "----3 The Emperor, seeing the realm newly settled, his sons young and his brothers few, took warning from Qin's fall through isolation and wished to enfeoff many men of his own surname to hold and pacify the realm." },
  { zh: "春，正月，丙午，分楚王信地為二國，以淮東五十三縣立從兄將軍賈為荊王，以薛郡、東海、彭城三十六縣立弟文信君交為楚王。", literal: "In spring, the first month, on bingwu, the territory of the King of Chu, Xin, was divided into two states: fifty-three counties east of the Huai were used to establish his elder cousin the general Jia as King of Jing, and thirty-six counties of Xue commandery, Donghai, and Pengcheng were used to establish his younger brother Lord Wenxin, Jiao, as King of Chu.", idiomatic: "In spring, the first month, on bingwu, King Xin of Chu's domain was split in two: fifty-three counties east of the Huai made his elder cousin General Jia King of Jing, and thirty-six counties of Xue, Donghai, and Pengcheng made his younger brother Lord Wenxin, Jiao, King of Chu." },
  { zh: "壬子，以雲中、雁門、代郡五十三縣立兄宜信侯喜為代王；", literal: "On renzi, fifty-three counties of Yunzhong, Yanmen, and Dai commanderies were used to establish his elder brother Marquis Yixin, Xi, as King of Dai;", idiomatic: "On renzi, fifty-three counties of Yunzhong, Yanmen, and Dai made his elder brother Marquis Yixin, Xi, King of Dai;" },
  { zh: "以膠東、膠西、臨淄、濟北、博陽、城陽郡七十三縣立微時外婦之子肥為齊王，諸民能齊言者皆以與齊。", literal: "seventy-three counties of Jiaodong, Jiaoxi, Linzi, Jibei, Boyang, and Chengyang commanderies were used to establish Fei, son of his paramour in humble days, as King of Qi; all people who could speak the Qi tongue were given to Qi.", idiomatic: "seventy-three counties of Jiaodong, Jiaoxi, Linzi, Jibei, Boyang, and Chengyang made Fei, son of a concubine from his humble days, King of Qi, and every man who could speak Qi was assigned to Qi." },
  { zh: "----4上以韓王信材武，所王北近鞏、洛，南迫宛、葉，東有淮陽，皆天下勁兵處；", literal: "----4 The Emperor, considering that the King of Han, Xin, was talented and martial and that his kingdom on the north was near Gong and Luo, on the south pressed Wan and Ye, and on the east held Huaiyang—all places where the realm's strongest troops were stationed;", idiomatic: "----4 The Emperor judged King Xin of Han talented and martial, and his realm on the north lay near Gong and Luo, on the south pressed Wan and Ye, and on the east held Huaiyang—all seats of the realm's strongest armies;" },
  { zh: "乃以太原郡三十一縣為韓國，徙韓王信王太原以北，備御胡，都晉陽。", literal: "thereupon made thirty-one counties of Taiyuan commandery the state of Han, moved King Xin of Han to rule north of Taiyuan to guard against the Hu, and made his capital at Jinyang.", idiomatic: "so he made thirty-one Taiyuan counties the state of Han, moved King Xin to rule north of Taiyuan to guard against the barbarians, and set his capital at Jinyang." },
  { zh: "信上書曰：「國被邊，匈奴數入寇；", literal: "Xin memorialized, saying, “The state borders the frontier and the Xiongnu repeatedly raid;", idiomatic: "Xin memorialized: “The state borders the frontier and the Xiongnu raid again and again;" },
  { zh: "晉陽去塞遠，請治馬邑。", literal: "Jinyang is far from the passes; I ask to administer Mayi.", idiomatic: "Jinyang is far from the frontier; I ask to hold Mayi instead." },
  { zh: "」上許之。", literal: "” The Emperor granted it.", idiomatic: "” The Emperor agreed." },
  { zh: "----5上已封大功臣二十餘人，其餘日夜爭功不決，未得行封。", literal: "----5 The Emperor had already enfeoffed more than twenty great merit-holders; the rest disputed merit day and night without resolution, and the enfeoffments could not be carried out.", idiomatic: "----5 The Emperor had already enfeoffed more than twenty great merit-holders; the rest wrangled over merit day and night without end, and the remaining enfeoffments could not proceed." },
  { zh: "上在洛陽南宮，從覆道望見諸將，往往相與坐沙中語。", literal: "The Emperor was at the Southern Palace in Luoyang; from the covered walk he saw the generals often sitting together in the sand and talking.", idiomatic: "At the Southern Palace in Luoyang, from the covered walk he saw the generals often sitting together in the sand and talking." },
  { zh: "上曰：「此何語？", literal: "The Emperor said, “What are they saying?", idiomatic: "The Emperor said, “What are they saying?" },
  { zh: "」留侯曰：「陛下不知乎？", literal: "” The Marquis of Liu said, “Does Your Majesty not know?", idiomatic: "” The Marquis of Liu said, “Does Your Majesty not know?" },
  { zh: "此謀反耳！", literal: "They are plotting rebellion!", idiomatic: "They are plotting rebellion!" },
  { zh: "」上曰：「天下屬安定，何故反乎？", literal: "” The Emperor said, “The realm is nearly settled—why would they rebel?", idiomatic: "” The Emperor said, “The realm is nearly at peace—why would they rebel?" },
  { zh: "」留侯曰：「陛下起布衣，以此屬取天下。", literal: "” The Marquis of Liu said, “Your Majesty rose from common cloth and with these men took the realm.", idiomatic: "” The Marquis of Liu said, “Your Majesty rose from common cloth and with these men won the realm." },
  { zh: "今陛下為天子，而所封皆故人所親愛，所誅皆平生所仇怨。", literal: "Now Your Majesty is Son of Heaven, yet those enfeoffed are all old friends whom you love, and those executed are all lifelong enemies.", idiomatic: "Now you are Son of Heaven, yet you enfeoff only old friends you favor and execute only lifelong enemies." },
  { zh: "今軍吏計功，以天下不足遍封；", literal: "Now the army officers reckon merit, yet the realm is not enough to enfeoff them all;", idiomatic: "Officers reckon merit, yet the realm is not large enough to enfeoff them all;" },
  { zh: "此屬畏陛下不能盡封，恐又見疑平生過失及誅，故即相聚謀反耳。", literal: "these men fear that Your Majesty cannot enfeoff them fully, dread being suspected on account of past faults and executed, and therefore at once gather to plot rebellion.", idiomatic: "these men fear you cannot enfeoff them all, dread being seized on some past fault and killed, and so they gather at once to plot rebellion." },
  { zh: "」上乃憂曰：「為之奈何？", literal: "” The Emperor then said in distress, “What is to be done?", idiomatic: "” The Emperor said in distress, “What is to be done?" },
  { zh: "」留侯曰：「上平生所憎、群臣所共知，誰最甚者？", literal: "” The Marquis of Liu said, “Among those Your Majesty has hated all your life and whom the ministers all know, who is hated most?", idiomatic: "” The Marquis of Liu said, “Of those you have hated all your life and every minister knows it, who is hated most?" },
  { zh: "」上曰：「雍齒與我有故怨，數嘗窘辱我；", literal: "” The Emperor said, “Yong Chi and I have an old grudge; he has often shamed and insulted me;", idiomatic: "” The Emperor said, “Yong Chi and I have an old grudge; he has often shamed me;" },
  { zh: "我欲殺之，為其功多，故不忍。", literal: "I wished to kill him, but because his merit was great I could not bear to.", idiomatic: "I wanted to kill him, but his merit was great and I could not bear to." },
  { zh: "」留侯曰：「今急先封雍齒，則群臣人人自堅矣。", literal: "” The Marquis of Liu said, “If you urgently enfeoff Yong Chi first, then every minister will steady himself.", idiomatic: "” The Marquis of Liu said, “Enfeoff Yong Chi at once and every minister will feel secure." },
  { zh: "」於是上乃置酒，封雍齒為什方侯；", literal: "” Thereupon the Emperor set out wine, enfeoffed Yong Chi as Marquis of Shifang;", idiomatic: "” The Emperor then held a feast and made Yong Chi Marquis of Shifang;" },
  { zh: "而急趨丞相、御史定功行封。", literal: "and urgently urged the chancellor and the censor to fix merit and carry out the enfeoffments.", idiomatic: "and urgently ordered the chancellor and censor to fix merit and complete the enfeoffments." },
  { zh: "群臣罷酒，皆喜，曰：「雍齒尚為侯，我屬無患矣！", literal: "When the ministers left the feast they were all pleased and said, “Even Yong Chi has been made a marquis—we are safe!", idiomatic: "When the ministers left the feast they rejoiced and said, “Even Yong Chi is a marquis—we have nothing to fear!" },
  { zh: "::臣光曰：張良為高帝謀臣，委以心腹，宜其知無不言；", literal: ":: Minister Guang said: Zhang Liang was the High Emperor's planning minister, entrusted as his innermost confidant—it was fitting that he should speak without holding back;", idiomatic: ":: Minister Guang said: Zhang Liang was the High Emperor's strategist and trusted confidant; it was fitting that he should speak without reserve;" },
  { zh: "安有聞諸將謀反，必待高帝目見偶語，然後乃言之邪？", literal: "how could it be that, hearing the generals plot rebellion, he had to wait until the High Emperor saw them whispering together with his own eyes and only then speak?", idiomatic: "could he really have heard the generals plotting rebellion yet waited until the High Emperor saw them whispering in the sand before he spoke?" },
  { zh: "蓋以高帝初得天下，數用愛憎行誅賞，或時害至公，群臣往往有觖望自危之心，故良因事納忠以變移帝意，使上無阿私之失，下無猜懼之謀，國家無虞，利及後世。", literal: "Surely because the High Emperor had just gained the realm and often used love and hate to mete out punishment and reward, sometimes harming the utmost public good, the ministers often harbored resentment and a sense of peril—therefore Liang seized the occasion to offer loyal counsel and shift the Emperor's mind, so that above there was no partiality in error and below no plotting born of suspicion and fear, the state was without worry, and the benefit reached later generations.", idiomatic: "Surely because the High Emperor had just won the realm and often punished and rewarded by personal liking, sometimes harming the public good, the ministers often felt resentful and afraid—so Liang seized the occasion to offer loyal counsel and shift the emperor's mind, so that above there was no favoritism and below no plotting born of fear, the state was secure, and posterity benefited." },
  { zh: "若良者，可謂善諫矣。", literal: "One such as Liang may be called skilled at remonstrance.", idiomatic: "A man like Liang may truly be called skilled at remonstrance." },
  { zh: "----6列侯畢已受封，詔定元功十八人位次。", literal: "----6 When the ranked marquises had all received their enfeoffments, an edict fixed the order of rank among the eighteen chief merit-holders.", idiomatic: "----6 When the marquises had all received their fiefs, an edict fixed the order of rank among the eighteen chief merit-holders." },
  { zh: "皆曰：「平陽侯曹參，身被七十創，攻城略地，功最多，宜第一。", literal: "All said, “Marquis of Pingyang, Cao Shen, bore seventy wounds on his body, stormed cities and seized lands, and his merit was greatest—he should be first.", idiomatic: "All said, “Marquis of Pingyang Cao Shen bore seventy wounds, stormed cities and seized lands, and his merit was greatest—he should rank first." },
  { zh: "」謁者、關內侯鄂千秋進曰：「群臣議皆誤。", literal: "” The usher and Interior Marquis E Qianqiu advanced and said, “The ministers' deliberation is all wrong.", idiomatic: "” Usher and Interior Marquis E Qianqiu advanced and said, “The ministers are all wrong." },
  { zh: "夫曹參雖有野戰略地之功，此特一時之事耳。", literal: "Though Cao Shen has merit in field battle and seizing territory, that is only a matter of one season.", idiomatic: "Cao Shen's merit in field battle and seizing land is only a matter of one season." },
  { zh: "上與楚相距五歲，失軍亡眾，跳身遁者數矣，然蕭何常從關中遣軍補其處，非上所詔令召，而數萬眾會。", literal: "Your Majesty faced Chu for five years, lost armies and shed troops, and several times barely escaped with your life—yet Xiao He constantly sent armies from Guanzhong to fill the gaps; without edicts or summons from Your Majesty, tens of thousands would assemble.", idiomatic: "Your Majesty faced Chu for five years, lost armies and shed troops, and several times barely escaped—yet Xiao He constantly sent armies from Guanzhong to fill the gaps; without your summons, tens of thousands would appear." },
  { zh: "上之乏絕者數矣。", literal: "Your Majesty was brought to want several times.", idiomatic: "Your Majesty was brought to want again and again." },
  { zh: "又軍無見糧，蕭何轉漕關中，給食不乏。", literal: "Again, when the army had no grain in sight, Xiao He transported grain by water from Guanzhong and supplied food without fail.", idiomatic: "Again, when the army had no grain in sight, Xiao He shipped grain from Guanzhong and kept food from failing." },
  { zh: "陛下雖數亡山東，蕭何常全關中以待陛下。", literal: "Though Your Majesty several times lost the lands east of the mountains, Xiao He constantly held Guanzhong whole to await Your Majesty.", idiomatic: "Though Your Majesty several times lost the east, Xiao He constantly held Guanzhong intact awaiting your return." },
  { zh: "此萬世之功也。", literal: "This is merit for ten thousand generations.", idiomatic: "This is merit for ten thousand generations." },
  { zh: "今雖無曹參等百數，何缺於漢；", literal: "Now though there were no hundred-odd men like Cao Shen, what would Han lack?", idiomatic: "Now without a hundred men like Cao Shen, what would Han lack?" },
  { zh: "漢得之，不必待以全。", literal: "Han could gain the realm without waiting on them to be whole.", idiomatic: "Han could win the realm without them." },
  { zh: "奈何欲以一旦之功而加萬世之功哉！", literal: "How can you wish to set a moment's merit above merit for ten thousand generations!", idiomatic: "How can you set a moment's merit above merit for ten thousand generations!" },
  { zh: "蕭何第一，曹參次之。", literal: "Xiao He first, Cao Shen second.", idiomatic: "Xiao He first, Cao Shen second." },
  { zh: "」上曰：「善！", literal: "” The Emperor said, “Good!", idiomatic: "” The Emperor said, “Good!" },
  { zh: "」於是乃賜蕭何帶劍履上殿，入朝不趨。", literal: "” Thereupon he granted Xiao He the privilege to enter the hall with sword and shoes and not to hasten in audience.", idiomatic: "” Thereupon he granted Xiao He sword and shoes in the hall and exemption from hurrying in audience." },
  { zh: "上曰：「吾聞進賢受上賞。", literal: "The Emperor said, “I have heard that advancing the worthy receives the highest reward.", idiomatic: "The Emperor said, “I have heard that advancing the worthy wins the highest reward." },
  { zh: "蕭何功雖高，得鄂君乃益明。", literal: "Though Xiao He's merit was high, with Lord E it became still clearer.", idiomatic: "Xiao He's merit was high, but with Lord E it became still clearer." },
  { zh: "」於是因鄂千秋故所食邑，封為安平侯。", literal: "” Thereupon, on the strength of E Qianqiu's former fief, he was enfeoffed as Marquis of Anping.", idiomatic: "” Thereupon, on the basis of E Qianqiu's former fief, he was made Marquis of Anping." },
  { zh: "是日，悉封何父子兄弟十餘人，皆有食邑；", literal: "That day he enfeoffed more than ten of He's fathers, sons, and brothers, all with fiefs;", idiomatic: "That day he enfeoffed more than ten of He's fathers, sons, and brothers, each with a fief;" },
  { zh: "益封何二千戶。", literal: "and added two thousand households to He's fief.", idiomatic: "and added two thousand households to He's fief." },
  { zh: "----7上歸櫟陽。", literal: "----7 The Emperor returned to Liyang.", idiomatic: "----7 The Emperor returned to Liyang." },
  { zh: "----8夏，五月，丙午，尊太公為太上皇。", literal: "----8 In summer, the fifth month, on bingwu, the Grand Duke was honored as Grand Imperial Father.", idiomatic: "----8 In summer, the fifth month, on bingwu, the Grand Duke was honored as Grand Imperial Father." },
  { zh: "----9初，匈奴畏秦，北徙十餘年。", literal: "----9 At first the Xiongnu feared Qin and moved north for more than ten years.", idiomatic: "----9 At first the Xiongnu feared Qin and moved north for more than ten years." },
  { zh: "及秦滅，匈奴復稍南渡河。", literal: "When Qin perished, the Xiongnu again gradually moved south across the river.", idiomatic: "When Qin fell, the Xiongnu gradually moved south across the river again." },
  { zh: "單于頭曼有太子曰冒頓。", literal: "The shanyu Touman had a crown prince named Maodun.", idiomatic: "Shanyu Touman had a crown prince named Maodun." },
  { zh: "後有所愛閼氏，生少子，頭曼欲立之。", literal: "Later he favored a yanzhi who bore a younger son; Touman wished to establish him.", idiomatic: "Later he favored a consort who bore a younger son, and Touman wished to make him heir." },
  { zh: "是時，東胡強而月氏盛，乃使冒頓質於月氏。", literal: "At that time the Eastern Hu were strong and the Yuezhi flourished; he therefore sent Maodun as hostage to the Yuezhi.", idiomatic: "At that time the Eastern Hu were strong and the Yuezhi powerful, so he sent Maodun as hostage to the Yuezhi." },
  { zh: "既而頭曼急擊月氏，月氏欲殺冒頓。", literal: "Soon after, Touman pressed a swift attack on the Yuezhi; the Yuezhi wished to kill Maodun.", idiomatic: "Soon after Touman launched a swift attack on the Yuezhi, the Yuezhi meant to kill Maodun." },
  { zh: "冒頓盜其善馬騎之，亡歸；", literal: "Maodun stole their best horses, rode them, and fled back;", idiomatic: "Maodun stole their best horses, rode off, and fled home;" },
  { zh: "頭曼以為壯，令將萬騎。", literal: "Touman thought him stalwart and ordered him to command ten thousand horsemen.", idiomatic: "Touman judged him stalwart and gave him command of ten thousand horsemen." },
  { zh: "冒頓乃作鳴鏑，習勒其騎射。", literal: "Maodun then made whistling arrows and drilled his horsemen in shooting.", idiomatic: "Maodun then made whistling arrows and drilled his horsemen in shooting." },
  { zh: "令曰：「鳴鏑所射而不悉射者，斬之！", literal: "He ordered, “Whoever does not shoot at whatever the whistling arrow strikes shall be beheaded!", idiomatic: "He ordered, “Whoever does not shoot whatever the whistling arrow strikes shall be beheaded!" },
  { zh: "」冒頓乃以鳴鏑自射其善馬，既又射其愛妻；", literal: "” Maodun then shot his own best horse with the whistling arrow, and afterward shot his beloved wife;", idiomatic: "” Maodun shot his own best horse with the whistling arrow, then his beloved wife;" },
  { zh: "左右或不敢射者，皆斬之。", literal: "those at his side who dared not shoot were all beheaded.", idiomatic: "any at his side who dared not shoot were beheaded." },
  { zh: "最後以鳴鏑射單于善馬，左右皆射之。", literal: "At last he shot the shanyu's best horse with the whistling arrow, and those at his side all shot.", idiomatic: "At last he shot the shanyu's best horse with the whistling arrow, and all at his side shot." },
  { zh: "於是冒頓知其可用。", literal: "Thereupon Maodun knew they could be used.", idiomatic: "Then Maodun knew they would obey." },
  { zh: "從頭曼獵，以鳴鏑射頭曼，其左右亦皆隨鳴鏑而射。", literal: "On a hunt with Touman he shot Touman with the whistling arrow, and those at his side also all shot as the whistling arrow sounded.", idiomatic: "On a hunt with Touman he shot Touman with the whistling arrow, and his men shot with him." },
  { zh: "遂殺頭曼，盡誅其後母與弟及大臣不聽從者。", literal: "He then killed Touman and put to death all his stepmother, younger brothers, and ministers who would not obey.", idiomatic: "He killed Touman and put to death his stepmother, younger brothers, and every minister who would not obey." },
  { zh: "冒頓自立為單于。", literal: "Maodun established himself as shanyu.", idiomatic: "Maodun made himself shanyu." },
  { zh: "東胡聞冒頓立，乃使使謂冒頓：「欲得頭曼時千里馬。", literal: "The Eastern Hu, hearing Maodun had established himself, sent envoys to tell Maodun, “We wish to have the thousand-li horse from Touman's time.", idiomatic: "The Eastern Hu, hearing Maodun had made himself shanyu, sent envoys saying, “We want Touman's thousand-li horse." },
  { zh: "」冒頓問群臣，群臣皆曰：「此匈奴寶馬也，勿與！", literal: "” Maodun asked his ministers; they all said, “This is a treasure horse of the Xiongnu—do not give it!", idiomatic: "” Maodun asked his ministers; they all said, “This is a Xiongnu treasure horse—do not give it!" },
  { zh: "」冒頓日；", literal: "” Maodun said;", idiomatic: "” Maodun said;" },
  { zh: "「奈何與人鄰國而愛一馬乎！", literal: "“How can one be neighbor to a state and cherish a single horse!", idiomatic: "“How can one border a state and cling to one horse!" },
  { zh: "」遂與之。", literal: "” He then gave it.", idiomatic: "” He gave it." },
  { zh: "居頃之，東胡又使使謂冒頓：「欲得單于一閼氏。", literal: "After a short while the Eastern Hu again sent envoys to tell Maodun, “We wish to have one yanzhi of the shanyu.", idiomatic: "Before long the Eastern Hu again sent envoys saying, “We want one of the shanyu's consorts." },
  { zh: "」冒頓復問左右，左右皆怒曰：「東胡無道，乃求閼氏！", literal: "” Maodun again asked those at his side; they all said in anger, “The Eastern Hu are lawless—yet they ask for a yanzhi!", idiomatic: "” Maodun again asked his men; they said in anger, “The Eastern Hu are lawless—to ask for a consort!" },
  { zh: "請擊之！", literal: "We ask to strike them!", idiomatic: "Let us attack them!" },
  { zh: "」冒頓曰：「奈何與人鄰國愛一女子乎！", literal: "” Maodun said, “How can one be neighbor to a state and cherish one woman!", idiomatic: "” Maodun said, “How can one border a state and cling to one woman!" },
  { zh: "」遂取所愛閼氏予東胡。", literal: "” He then took the yanzhi he loved and gave her to the Eastern Hu.", idiomatic: "” He gave the consort he loved to the Eastern Hu." },
  { zh: "東胡王愈益驕。", literal: "The king of the Eastern Hu grew still more arrogant.", idiomatic: "The king of the Eastern Hu grew still more arrogant." },
  { zh: "東胡與匈奴中間有棄地莫居，千餘里，各居其邊，為甌脫。", literal: "Between the Eastern Hu and the Xiongnu lay abandoned land no one inhabited, more than a thousand li; each held its border as ou tuo.", idiomatic: "Between the Eastern Hu and the Xiongnu lay more than a thousand li of abandoned land no one inhabited; each held the border as ou tuo." },
  { zh: "東胡使使謂冒頓：「此棄地，欲有之。", literal: "The Eastern Hu sent envoys to tell Maodun, “This abandoned land—we wish to have it.", idiomatic: "The Eastern Hu sent envoys saying, “This abandoned land—we want it." },
  { zh: "」冒頓問群臣，群臣或曰：「此棄地，予之亦乎，勿與亦可！", literal: "” Maodun asked his ministers; some said, “This is abandoned land—giving it is also fine, not giving it is also acceptable!", idiomatic: "” Maodun asked his ministers; some said, “It is abandoned land—give it or withhold it, either is fine!" },
  { zh: "」於是冒頓大怒曰：「地者，國之本也，奈何予之！", literal: "” Thereupon Maodun said in great anger, “Land is the root of a state—how can it be given!", idiomatic: "” Maodun flew into a rage and said, “Land is the root of a state—how can it be given away!" },
  { zh: "」諸言予之者，皆斬之。", literal: "” All who spoke of giving it were beheaded.", idiomatic: "” All who spoke of giving it were beheaded." },
  { zh: "冒頓上馬，令：「國中有後出者斬！", literal: "Maodun mounted his horse and ordered, “Whoever leaves the state last shall be beheaded!", idiomatic: "Maodun mounted and ordered, “Whoever leaves the realm last shall be beheaded!" },
  { zh: "」遂襲擊東胡。", literal: "” He then struck the Eastern Hu by surprise.", idiomatic: "” He then struck the Eastern Hu by surprise." },
  { zh: "東胡初輕冒頓，不為備；", literal: "At first the Eastern Hu despised Maodun and made no preparations;", idiomatic: "At first the Eastern Hu despised Maodun and made no preparations;" },
  { zh: "冒頓遂滅東胡。", literal: "Maodun then destroyed the Eastern Hu.", idiomatic: "Maodun destroyed the Eastern Hu." },
  { zh: "既歸，又西擊走月氏，南並樓煩、白羊河南王，遂侵燕、代，悉收蒙恬所奪匈奴故地與漢關故河南塞至朝那、膚施。", literal: "After returning he again struck west and drove off the Yuezhi, south annexed the kings of Loufan and the White Sheep south of the river, then invaded Yan and Dai, and wholly recovered the former Xiongnu lands seized by Meng Tian and the old Henan barrier of the Han passes as far as Chaona and Fushi.", idiomatic: "On his return he drove the Yuezhi west, annexed the Loufan and White Sheep kings south of the river, invaded Yan and Dai, and recovered all the former Xiongnu lands Meng Tian had taken and the old Henan barrier of the Han passes as far as Chaona and Fushi." },
  { zh: "是時，漢兵方與項羽相距，中國罷於兵革，以故冒頓得自強，控弦之士三十餘萬，威服諸國。", literal: "At that time Han troops were still facing Xiang Yu and the central lands were exhausted by arms; for this reason Maodun was able to strengthen himself, had more than three hundred thousand bowmen, and awed and subdued the states.", idiomatic: "At that time Han was still facing Xiang Yu and the central lands were exhausted by war; Maodun therefore grew strong, mustered more than three hundred thousand bowmen, and awed the states into submission." },
  { zh: "秋，匈奴圍韓王信於馬邑。", literal: "In autumn the Xiongnu besieged King Xin of Han at Mayi.", idiomatic: "In autumn the Xiongnu besieged King Xin of Han at Mayi." },
  { zh: "信數使使胡，求和解。", literal: "Xin repeatedly sent envoys to the Hu to seek peace.", idiomatic: "Xin repeatedly sent envoys to the Xiongnu seeking peace." },
  { zh: "漢發兵救之。", literal: "Han sent troops to rescue him.", idiomatic: "Han sent troops to rescue him." },
  { zh: "疑信數間使，有二心，使人責讓信。", literal: "Suspecting that Xin had repeatedly sent secret envoys and held two hearts, Han sent men to rebuke him.", idiomatic: "Suspecting repeated secret missions and divided loyalty, Han sent men to rebuke him." },
  { zh: "信恐誅，九月，以馬邑降匈奴。", literal: "Xin feared execution; in the ninth month he surrendered Mayi to the Xiongnu.", idiomatic: "Fearing execution, in the ninth month he surrendered Mayi to the Xiongnu." },
  { zh: "匈奴冒頓因引兵南逾句注，攻太原，至晉陽。", literal: "The Xiongnu shanyu Maodun thereupon led his army south across Juzhu, attacked Taiyuan, and reached Jinyang.", idiomatic: "Shanyu Maodun of the Xiongnu led his army south across Juzhu, attacked Taiyuan, and reached Jinyang." },
  { zh: "----10帝悉去秦苛儀法，為簡易。", literal: "----10 The Emperor wholly abolished Qin's harsh rites and laws and made them simple and easy.", idiomatic: "----10 The Emperor abolished Qin's harsh rites and laws and made them simple and easy." },
  { zh: "群臣飲酒爭功，醉，或妄呼，拔劍擊柱，帝益厭之。", literal: "The ministers drank wine and disputed merit; drunk, some shouted wildly and drew swords to strike the pillars—the Emperor grew still more weary of it.", idiomatic: "Ministers drank and wrangled over merit; drunk, some shouted wildly and drew swords to strike the pillars—the Emperor grew still more weary of it." },
  { zh: "叔孫通說上曰：「夫儒者難與進取，可與守成。", literal: "Shusun Tong advised the Emperor, saying, “Confucians are hard to advance with for aggressive gain, but can be used to preserve what is achieved.", idiomatic: "Shusun Tong advised the Emperor, saying, “Confucians are hard to use for bold advance, but excellent for preserving what is won." },
  { zh: "臣願征魯諸生，與臣弟子共起朝儀。", literal: "Your servant wishes to summon the scholars of Lu and, together with your servant's disciples, establish court ceremony.", idiomatic: "Your servant wishes to summon the scholars of Lu and, with my disciples, establish court ceremony." },
  { zh: "」帝曰：「得無難乎？", literal: "” The Emperor said, “Will it not be difficult?", idiomatic: "” The Emperor said, “Won't that be difficult?" },
  { zh: "」叔孫通曰：「五帝異樂，三王不同禮，禮者，因時世、人情為之節文者也。", literal: "” Shusun Tong said, “The Five Emperors had different music; the Three Kings had different rites. Rites are the patterned forms made according to the age and human sentiment.", idiomatic: "” Shusun Tong said, “The Five Emperors had different music; the Three Kings had different rites. Rites are patterned forms shaped to the times and human feeling." },
  { zh: "臣願頗采古禮，與秦儀雜就之。", literal: "Your servant wishes to draw somewhat on ancient rites and blend them with Qin ceremony to complete them.", idiomatic: "Your servant wishes to draw on ancient rites and blend them with Qin ceremony to complete the system." },
  { zh: "」上曰：「可試為之，令易知，度吾所能行者為之。", literal: "” The Emperor said, “You may try to make them; make them easy to understand, and measure them by what I can perform.", idiomatic: "” The Emperor said, “Try it—make it easy to understand, and shape it to what I can actually perform." },
  { zh: "於是叔孫通使徵魯諸生三十餘人。", literal: "Thereupon Shusun Tong sent to summon more than thirty scholars of Lu.", idiomatic: "Thereupon Shusun Tong sent to summon more than thirty scholars of Lu." },
  { zh: "魯有兩生不肯行，曰：「公所事者且十主，皆面諛以得親貴。", literal: "In Lu two scholars refused to go and said, “The lords you have served number nearly ten; all were flattered to your face to win favor and rank.", idiomatic: "In Lu two scholars refused to go, saying, “You have served nearly ten lords, flattering each to your face to win favor and rank." },
  { zh: "今天下初定，死者未葬，傷者未起，又欲起禮、樂。", literal: "Now the realm is newly settled; the dead are not yet buried, the wounded not yet risen—and you wish again to raise rites and music.", idiomatic: "The realm is newly settled; the dead are unburied, the wounded unrestored—and you wish to raise rites and music again." },
  { zh: "禮、樂所由起，積德百年而後可興也。", literal: "That from which rites and music arise requires a hundred years of accumulated virtue before they can flourish.", idiomatic: "Rites and music arise only after a hundred years of accumulated virtue." },
  { zh: "吾不忍為公所為。", literal: "We cannot bear to do what you do.", idiomatic: "We cannot bear to do as you do." },
  { zh: "公去矣，無污我！", literal: "Go, sir—do not defile us!", idiomatic: "Go, sir—do not defile us!" },
  { zh: "」叔孫通笑曰：「若真鄙儒也，不知時變。", literal: "” Shusun Tong laughed and said, “You are truly petty Ru—ignorant of changing times.", idiomatic: "” Shusun Tong laughed and said, “You are truly petty pedants, ignorant of changing times." },
  { zh: "」遂與所徵三十人西，及上左右為學者與其弟子百餘人，為綿蕞，野外習之。", literal: "” He then went west with the thirty he had summoned, together with more than a hundred scholars among the Emperor's attendants and his own disciples; they made a fence of felt and practiced in the open country.", idiomatic: "” He then went west with the thirty he had summoned, together with more than a hundred court scholars and his own disciples; they set up a felt enclosure and drilled in the open country." },
  { zh: "月餘，言於上曰：「可試觀矣。", literal: "After more than a month he told the Emperor, “You may try to observe.", idiomatic: "After more than a month he told the Emperor, “You may try to observe." },
  { zh: "」上使行禮，曰：「吾能為此。", literal: "” The Emperor had the rites performed and said, “I can do this.", idiomatic: "” The Emperor had the rites performed and said, “I can do this." },
  { zh: "」乃令群臣習肄。", literal: "” He then ordered the ministers to practice and drill.", idiomatic: "” He then ordered the ministers to practice." },
  { zh: "1冬，十月，長樂宮成，諸侯群臣皆朝賀。", literal: "1 In winter, the tenth month, the Changle Palace was completed; the feudal lords and ministers all came to court to offer congratulations.", idiomatic: "1 In winter, the tenth month, the Changle Palace was completed, and feudal lords and ministers all came to court to congratulate." },
  { zh: "先平明，謁者治禮，以次引入殿門，陳東、西鄉。", literal: "Before dawn the ushers arranged the rites and led them in order through the hall gates, arrayed in east and west ranks.", idiomatic: "Before dawn the ushers arranged the rites and led them in order through the hall gates, arrayed in east and west ranks." },
  { zh: "衛官俠陛及羅立廷中，皆執兵，張旗幟。", literal: "Guard officers stood along the steps and in ranks in the courtyard, all holding weapons and displaying banners and pennants.", idiomatic: "Guards lined the steps and stood in ranks in the courtyard, all armed and displaying banners." },
  { zh: "於是皇帝傳警，輦出房；", literal: "Thereupon the Emperor sounded the alarm and the carriage came out from the side chamber;", idiomatic: "The Emperor sounded the alarm and the carriage came out from the side chamber;" },
  { zh: "引諸侯王以下至吏六百石以次奉賀，莫不振恐肅敬。", literal: "the feudal kings and below down to officials of six hundred piculs were led in order to offer congratulations; none failed to tremble in awe and stand in reverence.", idiomatic: "kings and below down to officials of six hundred piculs were led in order to offer congratulations; none failed to tremble in awe and stand in reverence." },
  { zh: "至禮畢，復置法酒。", literal: "When the rites were finished, regulated wine was set out again.", idiomatic: "When the rites were finished, regulated wine was set out again." },
  { zh: "諸侍坐殿上，皆伏，抑首；", literal: "All who sat in attendance in the hall crouched low and bowed their heads;", idiomatic: "All who sat in attendance in the hall crouched low and bowed their heads;" },
  { zh: "以尊卑次起上壽。", literal: "according to rank of honor they rose in order to offer the toast of longevity.", idiomatic: "and by rank of honor rose in order to offer the toast of longevity." },
  { zh: "觴九行，謁者言「置酒」，御史執法舉不如儀者，輒引去。", literal: "After nine rounds of the cup the usher announced “Set out wine”; the censor enforced the law and reported anyone not conforming to the rites, who was at once led away.", idiomatic: "After nine rounds the usher announced “Set out wine”; the censor reported anyone not conforming to the rites, who was at once led away." },
  { zh: "竟朝置酒，無敢讙嘩失禮者。", literal: "Through the whole audience with wine set out, none dared shout, clamor, or breach ritual.", idiomatic: "Through the whole audience with wine, none dared shout, clamor, or breach ritual." },
  { zh: "於是帝曰：「吾乃今日知為皇帝之貴也！", literal: "Thereupon the Emperor said, “Only today do I know the honor of being emperor!", idiomatic: "The Emperor said, “Only today do I know the honor of being emperor!" },
  { zh: "」乃拜叔孫通為太常，賜金五百斤。", literal: "” He then appointed Shusun Tong Grand Master of Ceremonies and granted him five hundred jin of gold.", idiomatic: "” He appointed Shusun Tong Grand Master of Ceremonies and granted him five hundred jin of gold." },
  { zh: "初，秦有天下，悉內六國禮儀，采擇其尊君、抑臣者存之。", literal: "At first, when Qin held the realm, it took in all the rites and ceremonies of the six states and selected and kept those that honored the ruler and humbled the minister.", idiomatic: "At first, when Qin held the realm, it absorbed the rites of the six states and kept those that honored the ruler and humbled the minister." },
  { zh: "及通制禮，頗有所增損，大抵皆襲秦故，自天子稱號下至佐僚及宮室、官名，少所變改。", literal: "When Tong fixed the rites he somewhat added and subtracted, but on the whole all followed Qin precedent; from the Son of Heaven's titles down to assistants and clerks, palace chambers and official names, little was changed.", idiomatic: "When Tong fixed the rites he made some changes, but on the whole followed Qin precedent; from the Son of Heaven's titles down to assistants, palace chambers, and official names, little was altered." },
  { zh: "其書，後與律、令同錄，藏於理官。", literal: "His book was later copied together with statutes and ordinances and stored in the office of the chief judge.", idiomatic: "His book was later copied together with statutes and ordinances and stored in the chief judge's office." },
  { zh: "法家又復不傳，民臣莫有言者焉。", literal: "The Legalists again did not transmit it, and among the people and ministers none spoke of it.", idiomatic: "The Legalists did not transmit it again, and among the people and ministers none spoke of it." },
  { zh: "::臣光曰：禮之為物大矣！", literal: ":: Minister Guang said: As a thing, ritual is great indeed!", idiomatic: ":: Minister Guang said: Ritual as a thing is great indeed!" },
  { zh: "用之於身，則動靜有法而百行備焉；", literal: "Applied to the person, then movement and stillness have law and the hundred conduct-lines are complete;", idiomatic: "Applied to the person, movement and stillness have law and the hundred conduct-lines are complete;" },
  { zh: "用之於家，則內外有別而九族睦焉；", literal: "applied to the household, then inner and outer have distinction and the nine kindreds are harmonious;", idiomatic: "applied to the household, inner and outer have distinction and the nine kindreds are harmonious;" },
  { zh: "用之於鄉，則長幼有倫而俗化美焉；", literal: "applied to the district, then elder and younger have order and custom is transformed and made beautiful;", idiomatic: "applied to the district, elder and younger have order and custom is transformed and beautified;" },
  { zh: "用之於國，則君臣有敘而政治成焉；", literal: "applied to the state, then ruler and minister have sequence and governance is accomplished;", idiomatic: "applied to the state, ruler and minister have order and governance is accomplished;" },
  { zh: "用之於天下，則諸侯順服而紀綱正焉；", literal: "applied to all under Heaven, then the feudal lords submit and the cords and net are set right;", idiomatic: "applied to all under Heaven, the feudal lords submit and the cords and net are set right;" },
  { zh: "豈直幾席之上、戶庭之間得之而不亂哉！", literal: "how could it be only on mats and seats, within doors and courtyards, that one gains it and is not disordered!", idiomatic: "could it be only on mats and seats, within doors and courtyards, that one gains it and is not disordered!" },
  { zh: "夫以高祖之明達，聞陸賈之言而稱善，睹叔孫通之儀而歎息；", literal: "That the High Emperor was so clear-sighted—he heard Lu Jia's words and praised them, beheld Shusun Tong's ceremony and sighed;", idiomatic: "The High Emperor was so clear-sighted—he heard Lu Jia's words and praised them, beheld Shusun Tong's ceremony and sighed;" },
  { zh: "然所以不能比肩於三代之王者，病於不學而已。", literal: "yet he could not stand shoulder to shoulder with the kings of the Three Dynasties—the ailment lay only in not studying.", idiomatic: "yet he could not stand shoulder to shoulder with the kings of the Three Dynasties—the fault lay only in not studying." },
  { zh: "當是之時，得大儒而佐之，與之以禮為天下，其功烈豈若是而止哉！", literal: "At that time, had he obtained a great Ru to assist him and entrusted the realm to him through ritual, would his achievements and glory have stopped at only this!", idiomatic: "At that time, had he obtained a great Confucian to assist him and entrusted the realm to ritual, would his achievements have stopped at only this!" },
  { zh: "惜夫，叔孫生之為器小也！", literal: "Alas! Master Shusun's vessel was small!", idiomatic: "Alas! Master Shusun's capacity was small!" },
  { zh: "徒竊禮之糠枇，以依世、諧俗、取寵而已，遂使先王之禮淪沒而不振，以迄於今，豈不痛甚矣哉！", literal: "He merely stole the chaff and lees of ritual to conform to the age, harmonize with custom, and win favor—that was all—and thereby caused the former kings' ritual to sink away and fail to revive, down to the present. How is this not grievously painful!", idiomatic: "He merely stole the chaff of ritual to conform to the age, harmonize with custom, and win favor—and thereby caused the former kings' ritual to sink away unre revived, down to the present. How grievously painful!" },
  { zh: "是以揚子譏之曰：「昔者魯有大臣，史失其名，曰：『何如其大也！", literal: "Therefore Yangzi mocked him, saying, “Of old in Lu there was a great minister whose name the histories have lost. It was said, ‘How great he was!", idiomatic: "Therefore Yangzi mocked him, saying, “Of old in Lu there was a great minister whose name the histories have lost. It was said, ‘How great he was!" },
  { zh: "』曰：『叔孫通欲制君臣之儀，召先生於魯，所不能致者二人。", literal: "’ It was said, ‘Shusun Tong wished to fix ceremony between ruler and minister and summoned the masters from Lu; two whom he could not bring.’", idiomatic: "’ It was said, ‘Shusun Tong wished to fix ceremony between ruler and minister and summoned the masters from Lu; two he could not bring.’" },
  { zh: "』曰：『若是，則仲尼之開跡諸侯也非邪？", literal: "’ It was said, ‘If so, was not Zhongni's opening his traces among the feudal lords also wrong?", idiomatic: "’ It was said, ‘If so, was not Confucius's opening his traces among the feudal lords also wrong?" },
  { zh: "」曰：『仲尼開跡，將以自用也。", literal: "” It was said, ‘Zhongni opened his traces intending to use them himself.", idiomatic: "” It was said, ‘Confucius opened his traces intending to use them himself." },
  { zh: "如委己而從人，雖有規矩、準繩，焉得而用之！", literal: "If one abandons oneself and follows others, though there be compass and square, plumb line and marking-cord—how could one apply them!", idiomatic: "If one abandons oneself and follows others, though there be compass, square, plumb line, and marking-cord—how could one apply them!" },
  { zh: "』」善乎揚子之言也！", literal: "’” How excellent are Yangzi's words!", idiomatic: "’” How excellent are Yangzi's words!" },
  { zh: "夫大儒者，惡肯毀其規矩、準繩以趨一時之功哉！", literal: "Would a great Ru be willing to destroy his compass and square, plumb line and marking-cord, to rush after merit of one season!", idiomatic: "Would a great Confucian destroy his compass, square, plumb line, and marking-cord to rush after momentary merit!" },
  { zh: "2上自將擊韓王信，破其軍於銅鞮，斬其將王喜。", literal: "2 The Emperor personally led troops to strike King Xin of Han, broke his army at Tongdi, and beheaded his general Wang Xi.", idiomatic: "2 The Emperor personally led troops against King Xin of Han, broke his army at Tongdi, and beheaded his general Wang Xi." },
  { zh: "信亡走匈奴；", literal: "Xin fled and went to the Xiongnu;", idiomatic: "Xin fled to the Xiongnu;" },
  { zh: "白土人曼丘臣、王黃等立趙苗裔趙利為王，復收信敗散兵，與信及匈奴謀攻漢。", literal: "the men of Baitu, Manqiu Chen, Wang Huang, and others established Zhao Li, a scion of Zhao, as king, gathered again Xin's defeated and scattered troops, and with Xin and the Xiongnu plotted to attack Han.", idiomatic: "men of Baitu, Manqiu Chen, Wang Huang, and others made Zhao scion Zhao Li king, gathered Xin's defeated and scattered troops, and with Xin and the Xiongnu plotted to attack Han." },
  { zh: "匈奴使左、右賢王將萬餘騎，與王黃等屯廣武以南，至晉陽，漢兵擊之，匈奴輒敗走，已復屯聚，漢兵乘勝追之。", literal: "The Xiongnu sent the Left and Right Wise Kings to command more than ten thousand horsemen; with Wang Huang and others they encamped south of Guangwu as far as Jinyang. Han troops struck them; the Xiongnu at once fled in defeat, then gathered again, and Han troops pursued them exploiting victory.", idiomatic: "The Xiongnu sent the Left and Right Wise Kings with more than ten thousand horsemen; with Wang Huang and others they encamped south of Guangwu as far as Jinyang. Han struck them; the Xiongnu fled, regrouped, and Han pursued in victory." },
  { zh: "會天大寒，雨雪，士卒墮指者什二三。", literal: "It happened that Heaven was bitterly cold with rain and snow; two or three in ten of the soldiers lost fingers to frost.", idiomatic: "Heaven turned bitterly cold with rain and snow; two or three soldiers in ten lost fingers to frost." },
  { zh: "上居晉陽，聞冒頓居代谷，欲擊之。", literal: "The Emperor was at Jinyang and heard that Maodun was at Daigu; he wished to strike him.", idiomatic: "The Emperor was at Jinyang and heard Maodun was at Daigu; he wished to attack." },
  { zh: "使人覘匈奴，冒頓匿其壯士、肥牛馬，但見老弱及羸畜。", literal: "He sent men to reconnoiter the Xiongnu; Maodun hid his stalwart warriors and fat cattle and horses—only the old and weak and emaciated livestock were seen.", idiomatic: "He sent men to reconnoiter the Xiongnu; Maodun hid his warriors and fat cattle and horses—only the old, weak, and emaciated livestock were seen." },
  { zh: "使者十輩來，皆言匈奴可擊。", literal: "Ten rounds of envoys came back, all saying the Xiongnu could be struck.", idiomatic: "Ten rounds of envoys returned, all saying the Xiongnu could be attacked." },
  { zh: "上復使劉敬往使匈奴，未還；", literal: "The Emperor again sent Liu Jing as envoy to the Xiongnu; he had not yet returned;", idiomatic: "The Emperor again sent Liu Jing as envoy to the Xiongnu; he had not yet returned;" },
  { zh: "漢悉兵三十二萬北逐之，逾句注。", literal: "Han mobilized all troops, three hundred twenty thousand, to drive north and pursue them, crossing Juzhu.", idiomatic: "Han mobilized all troops—three hundred twenty thousand—to drive north in pursuit, crossing Juzhu." },
  { zh: "劉敬還，報曰：「兩國相擊，此宜誇矜，見所長。", literal: "Liu Jing returned and reported, “When two states strike each other, each should boast and display what is strong.", idiomatic: "Liu Jing returned and reported, “When two states fight, each should boast and display its strengths." },
  { zh: "今臣往，徒見羸瘠、老弱，此必欲見短，伏奇兵以爭利。", literal: "Now when your servant went, I saw only emaciated and old and weak persons—this must mean they wish to display weakness, with ambush troops lying in wait to contend for advantage.", idiomatic: "When I went I saw only the emaciated, old, and weak—this must mean they wish to display weakness while ambush troops lie in wait for advantage." },
  { zh: "愚以為匈奴不可擊也。", literal: "In my foolish view the Xiongnu cannot be struck.", idiomatic: "In my view the Xiongnu cannot be attacked." },
  { zh: "」是時，漢兵已業行，上怒，罵劉敬曰：「齊虜以口舌得官，今乃妄言沮吾軍！", literal: "” At that time Han troops had already set out on the march. The Emperor was angry and cursed Liu Jing, saying, “This Qi barbarian won office by the tongue—now he dares reckless words to thwart my army!", idiomatic: "” Han troops had already marched. The Emperor raged and cursed Liu Jing: “This Qi barbarian won office by talk—now he dares reckless words to thwart my army!" },
  { zh: "」械系敬廣武。", literal: "” He had Jing fettered and imprisoned at Guangwu.", idiomatic: "” He had Jing fettered and imprisoned at Guangwu." },
  { zh: "帝先至平城，兵未盡到；", literal: "The Emperor reached Pingcheng first; the troops had not all arrived;", idiomatic: "The Emperor reached Pingcheng first; the troops had not all arrived;" },
  { zh: "冒頓縱精兵四十萬騎，圍帝於白登七日，漢兵中外不得相救餉。", literal: "Maodun released four hundred thousand picked horsemen and besieged the Emperor at Baideng for seven days; Han troops within and without could not rescue or supply one another.", idiomatic: "Maodun released four hundred thousand picked horsemen and besieged the Emperor at Baideng for seven days; Han forces within and without could not rescue or supply one another." },
  { zh: "帝用陳平秘計，使使間厚遺閼氏。", literal: "The Emperor used Chen Ping's secret plan and sent envoys through intermediaries to present rich gifts to the yanzhi.", idiomatic: "The Emperor used Chen Ping's secret plan and sent envoys to present rich gifts to the yanzhi through intermediaries." },
  { zh: "閼氏謂冒頓曰：「兩主不相困。", literal: "The yanzhi said to Maodun, “Two rulers should not distress each other.", idiomatic: "The yanzhi said to Maodun, “Two rulers should not distress each other." },
  { zh: "今得漢地，而單于終非能居之也。", literal: "Even if you now gain Han territory, the shanyu in the end could not dwell in it.", idiomatic: "Even if you gain Han territory now, the shanyu could not dwell in it in the end." },
  { zh: "且漢主亦有神靈，單于察之！", literal: "Moreover the Han ruler also has spiritual power—shanyu, consider it!", idiomatic: "Moreover the Han ruler also has spiritual power—shanyu, consider it!" },
  { zh: "」冒頓與王黃、趙利期，而黃、利兵不來，疑其與漢有謀，乃解圍之一角。", literal: "” Maodun had an appointment with Wang Huang and Zhao Li, but Huang's and Li's troops did not come; suspecting they had dealings with Han, he then opened one corner of the encirclement.", idiomatic: "” Maodun had an appointment with Wang Huang and Zhao Li, but their troops did not come; suspecting collusion with Han, he opened one corner of the encirclement." },
  { zh: "會天大霧，漢使人往來，匈奴不覺。", literal: "It happened that Heaven sent great fog; Han envoys went back and forth and the Xiongnu did not notice.", idiomatic: "Heavy fog fell; Han messengers went back and forth and the Xiongnu did not notice." },
  { zh: "陳平請令強弩傅兩矢，外鄉，從解角直出。", literal: "Chen Ping asked that strong crossbows be fitted with two arrows each, facing outward, and that they go straight out through the opened corner.", idiomatic: "Chen Ping asked that strong crossbows be fitted with two arrows each, facing outward, and that they go straight out through the opened corner." },
  { zh: "帝出圍，欲驅；", literal: "The Emperor left the encirclement and wished to gallop;", idiomatic: "The Emperor left the encirclement and wished to gallop;" },
  { zh: "太僕滕公固徐行。", literal: "the Grand Master of the Stables, Duke of Teng, firmly made him go slowly.", idiomatic: "the Grand Master of the Stables, the Duke of Teng, firmly made him go slowly." },
  { zh: "至平城，漢大軍亦到，胡騎遂解去。", literal: "When they reached Pingcheng, Han's great army also arrived, and the Hu horsemen thereupon broke off and left.", idiomatic: "At Pingcheng Han's main army also arrived, and the barbarian horsemen broke off and left." },
  { zh: "漢亦罷兵歸，令樊噲止定代地。", literal: "Han also ceased the campaign and returned, ordering Fan Kuai to halt and settle the Dai region.", idiomatic: "Han also withdrew, ordering Fan Kuai to halt and settle the Dai region." },
  { zh: "上至廣武，赦劉敬，曰：「吾不用公言，以困平城；", literal: "When the Emperor reached Guangwu he pardoned Liu Jing and said, “I did not use your words and was trapped at Pingcheng;", idiomatic: "At Guangwu the Emperor pardoned Liu Jing and said, “I did not heed you and was trapped at Pingcheng;" },
  { zh: "吾皆已斬前使十輩矣。", literal: "I have already beheaded the former ten rounds of envoys.", idiomatic: "I have already beheaded the ten rounds of envoys who came before." },
  { zh: "」乃封敬二千戶為關內侯，號為建信侯。", literal: "” He then enfeoffed Jing with two thousand households as Interior Marquis, styled Marquis Jianxin.", idiomatic: "” He enfeoffed Jing with two thousand households as Interior Marquis, styled Marquis Jianxin." },
  { zh: "帝南過曲逆，曰：「壯哉縣！", literal: "The Emperor passed south through Quyu and said, “What a magnificent district!", idiomatic: "Passing south through Quyu the Emperor said, “What a magnificent district!" },
  { zh: "吾行天下，獨見洛陽與是耳。", literal: "I have traveled all under Heaven and have seen only Luoyang and this.", idiomatic: "I have traveled all under Heaven and seen only Luoyang and this." },
  { zh: "」乃更封陳平為曲逆侯，盡食之。", literal: "” He then changed Chen Ping's enfeoffment to Marquis of Quyu and granted him the full revenue.", idiomatic: "” He then made Chen Ping Marquis of Quyu and granted him the full revenue." },
  { zh: "平從帝征伐，凡六出奇計，輒益封邑焉。", literal: "Ping followed the Emperor on campaigns; in all six times he produced extraordinary stratagems, and each time his fief was increased.", idiomatic: "Ping followed the Emperor on campaign; six times he produced extraordinary stratagems, and each time his fief was increased." },
  { zh: "3十二月，上還，過趙。", literal: "3 In the twelfth month the Emperor returned and passed through Zhao.", idiomatic: "3 In the twelfth month the Emperor returned and passed through Zhao." },
  { zh: "趙王敖執子婿禮甚卑，上箕倨慢罵之。", literal: "The King of Zhao, Ao, performed the son-in-law's rites with great humility; the Emperor sat with legs spread, insolent and slow, and reviled him.", idiomatic: "King Ao of Zhao performed the son-in-law's rites with great humility; the Emperor sat with legs spread, insolent and slow, and reviled him." },
  { zh: "趙相貫高、趙午等皆怒，曰：「吾王，孱王也！", literal: "The Zhao chancellor Guan Gao, Zhao Wu, and others were all angry and said, “Our king is a weakling king!", idiomatic: "Zhao chancellor Guan Gao, Zhao Wu, and others were angry and said, “Our king is a weakling!" },
  { zh: "」乃說王曰：「天下豪桀並起，能者先立。", literal: "” They then urged the king, saying, “Heroes and champions rise together all under Heaven; the able are first established.", idiomatic: "” They urged the king: “Heroes rise together all under Heaven; the able are established first." },
  { zh: "今王事帝甚恭，而帝無禮；", literal: "Now Your Majesty serves the Emperor with great respect, yet the Emperor is without ritual;", idiomatic: "Your Majesty serves the Emperor with great respect, yet the Emperor shows no courtesy;" },
  { zh: "請為王殺之！", literal: "we ask to kill him for Your Majesty!", idiomatic: "let us kill him for Your Majesty!" },
  { zh: "」張敖嚙其指出血，曰：「君何言之誤！", literal: "” Zhang Ao bit his finger until it bled and said, “My lords, how wrong your words!", idiomatic: "” Zhang Ao bit his finger until it bled and said, “My lords, how wrong your words!" },
  { zh: "先人亡國，賴帝得復，德流子孫；", literal: "Our forebears lost their state; relying on the Emperor we were restored—his virtue flows to our sons and grandsons;", idiomatic: "Our forebears lost their state; relying on the Emperor we were restored—his virtue flows to our sons and grandsons;" },
  { zh: "秋豪皆帝力也。", literal: "even an autumn down is the Emperor's strength.", idiomatic: "even the slightest gain is the Emperor's gift." },
  { zh: "願君無復出口！", literal: "I wish you would speak no more of this!", idiomatic: "Speak no more of this!" },
  { zh: "」貫高、趙午等皆相謂曰：「乃吾等非也。", literal: "” Guan Gao, Zhao Wu, and the others said to one another, “It is we who are wrong.", idiomatic: "” Guan Gao, Zhao Wu, and the others said to one another, “We are in the wrong." },
  { zh: "吾王長者，不倍德；", literal: "Our king is a man of stature and will not betray virtue;", idiomatic: "Our king is a man of stature and will not betray virtue;" },
  { zh: "且吾等義不辱。", literal: "moreover in righteousness we cannot suffer disgrace.", idiomatic: "moreover in righteousness we cannot suffer disgrace." },
  { zh: "今帝辱我王，故欲殺之，何洿王為！", literal: "Now the Emperor insults our king, so we wish to kill him—why stain the king with it!", idiomatic: "Now the Emperor has insulted our king, so we mean to kill him ourselves—why involve the king and defile him!" },
  { zh: "事成歸王，事敗獨身坐耳！", literal: "If the deed succeeds, credit returns to the king; if it fails, we alone bear punishment!", idiomatic: "If we succeed, the credit goes to the king; if we fail, we alone bear the penalty!" },
  { zh: "4匈奴攻代。", literal: "4. The Xiongnu attacked Dai.", idiomatic: "4. The Xiongnu attacked Dai." },
  { zh: "代王喜棄國自歸，赦為郃陽侯。", literal: "King Xi of Dai abandoned his state and surrendered of his own accord; he was pardoned and made Marquis of Heyang.", idiomatic: "King Xi of Dai abandoned his kingdom and came in of his own accord; he was pardoned and made Marquis of Heyang." },
  { zh: "辛卯，立皇子如意為代王。", literal: "On xinmao, the imperial son Ruyi was established as King of Dai.", idiomatic: "On xinmao, the imperial son Ruyi was made King of Dai." },
  { zh: "5春，二月，上至長安。", literal: "5. In spring, the second month, the Emperor arrived at Chang'an.", idiomatic: "5. In spring, the second month, the Emperor reached Chang'an." },
  { zh: "蕭何治未央宮，上見其壯麗，甚怒，謂何曰：「天下匈匈，苦戰數歲，成敗未可知，是何治宮室過度也！", literal: "Xiao He was building Weiyang Palace; when the Emperor saw how grand it was he was greatly angered and said to He, “All under Heaven is in turmoil; we have suffered bitter warfare for several years and success or defeat is not yet known—why does He build palaces to excess!", idiomatic: "Xiao He was building Weiyang Palace; when the Emperor saw how grand it was he flew into a rage and said to He, “The realm is in turmoil; we have fought bitterly for years and success or defeat are still uncertain—why are you building palaces to excess!" },
  { zh: "」何曰：「天下方未定，故可因以就宮室。", literal: "” He said, “All under Heaven is not yet settled, so one may take advantage of this to complete the palace.", idiomatic: "” He said, “The realm is not yet settled, so this is the time to finish the palace." },
  { zh: "且夫天子以四海為家，非壯麗無以重威，且無令後世有以加也。", literal: "Moreover, the Son of Heaven takes the four seas as his home; without grandeur there is no means to augment authority, and moreover do not let later ages have anything by which to surpass it.", idiomatic: "Moreover, the Son of Heaven takes the four seas as his home; without grandeur there is no way to lend weight to his authority, and do not let posterity have anything with which to surpass it." },
  { zh: "」上說。", literal: "” The Emperor was pleased.", idiomatic: "” The Emperor was pleased." },
  { zh: "::臣光曰：王者以仁義為麗，道德為威，未聞其以宮室填服天下也。", literal: ":: Minister Guang said: A true king takes benevolence and righteousness as adornment and virtue and the Way as awe; one has not heard of filling and subduing all under Heaven with palaces.", idiomatic: ":: Minister Guang said: A true king takes benevolence and righteousness as his splendor and virtue and the Way as his majesty; one has never heard of pacifying the realm with palaces." },
  { zh: "天下未定，當克己節用以趨民之急；", literal: "When all under Heaven is unsettled, one ought to restrain oneself and economize to rush to the people's urgent needs;", idiomatic: "When the realm is unsettled, one ought to restrain oneself and practice economy to meet the people's urgent needs;" },
  { zh: "而顧以宮室為先，豈可謂之知所務哉！", literal: "yet he turns instead to palaces first—can this be called knowing where to apply one's effort!", idiomatic: "yet he puts palaces first—can this be called knowing one's proper business!" },
  { zh: "昔禹卑宮室而桀為傾宮。", literal: "In antiquity Yu kept his palaces low while Jie built the Overturning Palace.", idiomatic: "In antiquity Yu kept his palaces humble while Jie built the Overturning Palace." },
  { zh: "創業垂統之君，躬行節儉以示子孫，其末流猶入於淫靡，況示之以侈乎！", literal: "Founding sovereigns who bequeath systems to posterity personally practice frugality to show their descendants; even their last offshoot still drifts into extravagance—how much more if they display extravagance to them!", idiomatic: "Founding sovereigns who bequeath their line personally practice frugality to teach their descendants; even their last heirs still sink into extravagance—how much more if they display extravagance to them!" },
  { zh: "乃雲「無令後世有以加」，豈不謬哉！", literal: "Yet he said, “Do not let later ages have anything by which to surpass it”—is this not absurd!", idiomatic: "Yet he said, “Do not let posterity surpass it”—is this not absurd!" },
  { zh: "至於孝武，卒以宮室罷敝天下，未必不由酇侯啟之也！", literal: "As for Emperor Wu, he finally exhausted and impoverished all under Heaven through palaces—this may well have been initiated by the Marquis of Zan!", idiomatic: "As for Emperor Wu, he finally wore out and impoverished the realm with palaces—perhaps it was indeed the Marquis of Zan who set him on that path!" },
  { zh: "6上自櫟陽徙都長安。", literal: "6. The Emperor moved his capital from Liyang to Chang'an.", idiomatic: "6. The Emperor moved his capital from Liyang to Chang'an." },
  { zh: "7初置宗正官，以序九族。", literal: "7. For the first time the Director of the Imperial Clan was established to order the nine kin-groups.", idiomatic: "7. For the first time the Director of the Imperial Clan was established to order the nine degrees of kin." },
  { zh: "8夏，四月，帝行如洛陽。", literal: "8. In summer, the fourth month, the Emperor traveled to Luoyang.", idiomatic: "8. In summer, the fourth month, the Emperor went to Luoyang." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
